INSERT INTO public.schema_versions (version, description) VALUES
  ('1.0.0', 'Merged monorepo + EXISTING_WORKING_CODE: geo tables, soft-delete, business-rule triggers, audit triggers, service logins')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.1.0', 'iam.user_org_mapping table, legal_entity_name/brand_name on entity.organizations, fixed multi-org RLS gaps')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.2.0', 'Meta Conversion API: ext.meta_org_config, ext.meta_leads, ext.meta_lead_custom_fields, ext.meta_capi_outbound_logs')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.3.0', 'Meta Conversion API: ext.meta_lead_addresses, ext.meta_lead_professional, ext.meta_lead_demographics, ext.meta_org_config.field_mappings, extended ext.view_meta_leads_complete')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.4.0', 'Meta Conversion API: tenant-level app config (ext.meta_tenant_config replaces per-org ext.meta_org_config) + ext.meta_page_form_org_map for Page/Form -> org attribution, ext.meta_leads.page_id')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.5.0', 'hr/task schemas, hr_svc/task_svc roles, entity.tenant_modules, HR lookups, hr.departments/designations, hr.employee_profiles, hr_admin role')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.6.0', 'Leave management: hr.holiday_calendars/holidays, leave_policies, hr_settings, leave_ledger, leave_requests (+status log), leave_request_approvals, hr.can_approve_leave(), leave views')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.6.1', 'Leave ledger accrual idempotency: unique (user, leave_type, entry_type, period) for accrual/carry_forward')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.7.0', 'Attendance: entity.organizations geo columns, hr.attendance_rules/shifts/shift_assignments, attendance_events (append-only), attendance_days, attendance_regularizations, hr.can_approve(), attendance views')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.15.0', 'P2.2A: effective-dated hr.reporting_lines (tenant/org scoped, RLS, no-overlap exclusion) as the HR approval-chain source of truth; backfilled from iam.users.manager_id, which degrades to an optional default')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.8.0', 'Tasks: task.task_statuses/task_priorities lookups, task.task_lists (owner-private RLS), task.tasks (+ status log + completion trigger), task.task_comments, task.vw_tasks_enriched')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.11.0', 'P1.1 Phase A (expand): per-product role catalogs (lms/hr/task.roles) + grants (member_roles) with RLS + fn_member_rank + vw_member_roles + iam.users.platform_role (nullable); global iam.user_roles ladder untouched')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.12.0', 'P1.1 Phase B (backfill): iam.users.platform_role + lms/hr/task.member_roles populated from iam.user_org_mapping ladder; idempotent, old ladder untouched')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.13.0', 'P1.2/D8: per-product DB role GRANTs — new lms_svc login; hr_svc/task_svc narrowed from blanket schema USAGE to own-schema DML + read-only iam/entity/geo; cross-product access explicitly revoked')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.14.0', 'P1.3: <product>.fn_member_role(user,org) -> (role,rank) resolver for per-service product-role resolution')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.17.0', 'Tenant default seeding: entity.catalog_defaults/catalog_versions (versioned per-product default catalogs) + entity.tenant_catalog_versions (per-tenant provisioning record, RLS) + entity.seed_tenant_defaults()/reset_tenant_catalog() functions; seeds v1 defaults for the 8 tenant-scoped lookups and backfills existing tenants')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.18.0', 'N-6 Half A: tenant-scoped admin write RLS + product-role write GRANTs on the 8 tenant-scoped lookup/role tables (lms.roles; hr.leave_types/employment_types/attendance_statuses/roles; task.task_statuses/task_priorities/roles) so product services own super_admin lookup writes without BYPASSRLS')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.20.0', 'Ladder roles hr_admin/org_sr_manager/org_manager/senior_sales_executive/sales_representative cloned per tenant (with capability grants) and repointed; only the four anchors super_admin/tenant_admin/org_admin/read_only remain global')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.23.0', 'Anchor roles tenant_admin/org_admin/read_only cloned per tenant (with capability grants) and repointed; super_admin is now the only global role')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.24.0', 'geo.countries/states/cities become a tenant-scoped catalog: UUID v7 PKs (was SMALLINT/INTEGER identity), tenant_id (NULL = platform template, cloned by entity.seed_tenant_geo()), is_active soft delete, RLS + tenant_admin writes, composite (tenant_id, x_id) FKs from entity.organizations; lms.marketing_leads geo FKs retyped to UUID and fenced by lms.check_lead_fk_org_scope(). Pre-migration tables archived in schema geo_archive.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.25.0', 'ext.lead_stage_capi_event_map tenant-scoped: tenant_id backfilled from lms.lead_stage (NULL = platform template), composite (tenant_id, stage_id) FK, RLS + write policy. Closes a cross-tenant read/write hole - app_user held SELECT/INSERT/UPDATE on a table with no tenant column and no RLS, so any tenant could read and repoint another tenant''s Meta conversion-event wiring. ext.vw_lead_stage_capi_event_map also gains security_invoker, without which it would leak past the new RLS.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.26.0', 'Three lookups tenants could not see. marketing.marketing_platforms/campaign_statuses: global UNIQUE (name) on an already tenant-scoped table made cloning impossible, so they were never provisioned and every tenant saw an empty dropdown - unique is now (tenant_id, name), templates cloned per tenant, and entity.seed_tenant_lms_catalogs() covers them going forward. hr.leave_request_statuses: the only one of four HR lookups left global - now tenant-scoped with RLS and provisioned from the catalog registry like its siblings.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.27.0', 'P4: single platform reporting hierarchy — hr.reporting_lines becomes iam.reporting_lines, read by LMS/HR/Tasks alike via iam.fn_is_in_subtree/fn_subtree_members/fn_manager_chain (effective-dated, as-of queryable); cross-org managers require an iam.user_org_mapping row; iam.users.manager_id demoted to a display mirror')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.28.0', 'Attendance regularizations escalate up the same iam.reporting_lines chain as leave: hr.attendance_regularization_approvals (one row per level) + hr.attendance_rules.regularization_approval_levels; hr_admin/org_admin/tenant_admin remain the any-level exception via hr.can_approve')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.29.0', 'hr.attendance_rules becomes tenant-scoped with an org override (tenant_id + nullable org_id, hr_settings-style precedence) and gains regularization_max_backdate_days — the admin-set window, in days, for how far back an attendance regularization may be filed; future-dated requests are always rejected')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.30.0', 'Per-employee geofence exemptions: hr.attendance_geo_exceptions (effective-dated, gist no-overlap scoped by type) names the people allowed to punch outside the fence — exception_type ''remote_role'' for rotating/field roles, ''wfh'' for an approved work-from-home stretch — replacing the all-or-nothing, self-declared attendance_rules.allow_wfh_checkin as the way to handle the few. hr.attendance_events.geo_exception_type records which kind let a punch through, so field work is never counted as working from home; a ''wfh'' exemption also sets is_wfh server-side, with no checkbox for the employee to forget or misuse.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.31.0', 'ext.meta_page_form_org_map.form_id made nullable for page-level Meta lead routing: a row with form_id NULL subscribes to every leadgen form on that Page, routing them all to the row''s org; an explicit form_id row still wins over the page-level fallback for pages shared across multiple orgs. New partial unique index uq_meta_page_form_org_map_page_level enforces at most one active page-level row per page.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.32.0', 'Public daily lead report page: lms.lead_report_snapshot (one row per branch+assignee per day, RLS-guarded, written by the existing send-lead-report cron job) so day-over-day comparison has history to read; branch/tenant rollups are derived via GROUPING SETS at read time rather than stored. New auth-constants scope lead-report:read on the existing iam.api_clients credential system — no new token table or issuance endpoint.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.33.0', 'Meta lead platform now sourced per-lead from Meta''s Graph API response (webhook + backfill scripts) instead of only the static ext.meta_page_form_org_map.platform config value, which had been defaulting nearly every Page/Form mapping to fb regardless of true placement. platform CHECK widened fb/ig -> fb/ig/wa on ext.meta_page_form_org_map and ext.meta_leads to support WhatsApp-sourced Lead Ads leads; lms.lead_sources.whatsapp (already seeded) is now reachable from ingestion.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.34.0', 'lms.lead_report_snapshot gains source_id/source_label so the public lead report''s per-source grids can compare against a prior day, not just live data. Unique key widened to (tenant_id, org_id, assigned_user_id, source_id, report_date); existing rows backfilled to source_id NULL / source_label ''Unknown''. send-lead-report.ts now writes one row per (branch, assignee, source) plus zero-fill placeholders per (branch, source), sourced from the same getTenantSourceReport() query the live page uses.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.35.0', 'New capability lms.history.detail.view — the Lead History dialog opened from a Leads History row now carries its own permission under the lms.history page instead of borrowing lms.leads.view / lms.leads.timeline.view from the Leads page. Denying the Leads page to org_admin/tenant_admin (2026-08-07) pruned those two operations and broke the dialog on a page both roles still hold. leads-service gains requireAnyCapability and accepts either key on GET /leads/:id, /leads/:id/timeline and /leads/:id/form-data; row scoping is untouched and still comes from lms.history.view''s scope ladder plus RLS. Back-filled for every role already holding lms.history.view, platform-default and per-tenant copies alike.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.36.0', 'Dedup-superseded leads (marketing_leads.superseded_by IS NOT NULL — an old lead replaced by a newer submission with the same org_id+phone/email) were only excluded from the daily lead-report views, leaking into every other operational surface: the main leads list, follow-up queue, org/tenant dashboards, rep leaderboard, and lead assignment endpoints. lms.vw_org_performance_snapshot, lms.vw_tenant_full_dashboard and lms.vw_rep_performance now additionally filter superseded_by IS NULL, matching the pattern vw_lead_report_branch/user already used; lms.vw_dashboard_leads is left unfiltered by design since its callers (leads-service listLeads/listFollowUps/assignments queries) now apply the same filter themselves so a direct-ID lookup (getLeadById) can still resolve a superseded lead.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.37.0', 'Lead assignment authority is now the capability ladder everywhere. iam.can_assign_to stopped resolving WHOM you may assign to from iam.reporting_lines (iam.fn_is_in_subtree) and now reads the seeded lms.leads.assign.reports/.peers/.any scopes against the target''s rank, matching @lms/authz''s canAssignToUser so the two write paths into a lead''s assignee — POST /assignments, and PATCH /leads/:id plus follow-up assignment — can no longer disagree. Under the old subtree rule, granting a role lms.leads.assign.peers had NO effect on the PATCH path, because a peer is by definition not in your reporting subtree; the seeded scope description ("Only people ranked below them") had always described rank, not reporting line. The three assign scopes are read in a single iam.fn_role_capability_matrix scan, so SQL and application code resolve tenant-override precedence and ancestor pruning identically; measured on production a matrix build is ~35ms warm, so one scan replaces what would have been ~100ms of per-key probing on every assignment write. Self-assignment stays unconditional on both paths. iam.reporting_lines remains the authority for hr.can_approve_leave and Tasks team scope — only lead assignment stopped reading it. No new capabilities, tables or RLS; lms.leads.assign.peers'' description text updated (self no longer depends on that rung).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.38.0', 'Lead follow-up scheduling is now enforced where the data lives, and an assignment note finally persists. lms.log_lead_assignment() reads the app.lead_transition_note GUC and writes lms.lead_assignment_log.note — a column that existed since the table was created and that nothing had ever populated: the Edit Lead dialog demanded a note for an assignment-only change and then dropped it, because lms.log_lead_stage_change() returns early when neither stage_id nor outcome_id moved and no other trigger recorded it. The assignment_change branch of lms.vw_lead_followup_timeline appends that note to its generated sentence so Lead History shows it. Notes are no longer mandatory client-side for a bare re-assignment; they remain mandatory for stage, outcome and follow-up changes, which are the edits the audit log actually keeps. Separately, leads-service now rejects any PATCH /leads/:id that would leave a lead in a stage with lead_stage.followup_required and marketing_leads.scheduled_at NULL — previously that rule lived only in the Edit Lead dialog, so a script, an integration, or the dialog itself when its stage-catalog fetch failed could park a lead in contacting/on_hold/qualified with no due time, making it invisible to the notifications-service poller (which requires scheduled_at IS NOT NULL) and to every overdue count. The follow-up is now created inside the same transaction as the stage move via the new follow_up_scheduled_at field, completing a follow-up on a lead still in such a stage requires the next due time, deleting a follow-up re-derives the pointer from the surviving pending row instead of leaving it dangling, and moving a lead out of a follow-up stage clears the stale timestamp. New partial index idx_marketing_leads_scheduled_at backs the poller and the overdue filters, which had been scanning unindexed.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.39.0', 'Lookup Admin coverage: hr.leave_request_statuses onboarded (hr-service /lookups/leave-request-statuses, reserved-name guard on its machine vocabulary); iam.departments becomes writable (was list-only, and was the required parent of iam.user_roles — a tenant with no seeded department could not have a role created for it); hr.designations onboarded as the console''s first org-scoped (rather than tenant-scoped) table, requiring a new admin_tenant_config_policy on hr.designations since hr_svc holds only app_user membership (07_grants.sql) and the table had no write path for a super_admin acting within a selected tenant+org — org_isolation_policy needs app.current_org_id (never set by the admin write helper) and tenant_isolation_policy needs the tenant_admin PG role hr_svc does not hold.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.40.0', 'Tier C cleanup: dropped the P1.1 per-product role ladders — lms/hr/task.roles + .member_roles, fn_member_rank, fn_member_role, vw_member_roles, public.set_member_role_tenant_id() and their catalog_defaults/catalog_versions seed rows (lms.roles/hr.roles/task.roles) — and their lookup-admin CRUD screens/routers. member_roles was never written by any code path (verified against a prod-restored copy: its populated rows trace to a since-removed backfill from iam.user_org_mapping); role/rank resolution has run on the single iam ladder via iam.fn_user_org_role since Tier C. api-gateway''s communicationSendGuard, the last reader, now calls resolveGlobalRole instead of the removed resolveMemberRole. See db_scripts/one_time for the one-off drop script for servers already carrying these objects.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.41.0', 'Lookup Admin coverage continued: hr.holiday_calendars/holidays/shifts onboarded as org-scoped lookups, each needing the same admin_tenant_config_policy added for hr.designations in 1.39.0 and for the same reason (hr_svc has no path to write an org-scoped table as app_user without app.current_org_id, nor as tenant_admin without the PG role). ext.meta_capi_event_types (global) and ext.lead_stage_capi_event_map (tenant-scoped, already RLS-covered by its existing admin_tenant_config_policy from 1.25.0) also gain admin surfaces; entity.tenant_modules becomes editable per tenant (previously SQL-only); entity.catalog_versions/tenant_catalog_versions gain a read-only drift report.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.42.0', 'Daily lead report now counts the whole lead catalog, not just the handful of metrics a screen happened to show. lms.vw_lead_report_branch and lms.vw_lead_report_user carry 29 metrics in one fixed grouped order — 6 core, one per lms.lead_stage (adding contacting/on_hold/qualified/transferred_out), and one per non-"other" lms.lead_stage_outcome (16, oc_ prefixed so the on_hold STAGE and on_hold OUTCOME do not collide on a column name), reached through a new LEFT JOIN lms.lead_stage_outcome on marketing_leads.outcome_id. Both views changed from CREATE OR REPLACE to DROP + CREATE: replace can only append columns and never reposition them, which is how new_leads_this_month had ended up stranded after snapshot_at, and appending 20 more would have compounded it. lms.lead_report_snapshot is dropped and recreated with the same 29 columns in the same order — its rows are day-over-day comparison history only, are not backfillable in any case (stage/outcome have moved since capture), and the page already degrades to "No snapshot recorded" for a missing date. The point of capturing every stage/outcome now rather than one at a time: a live counter can be added whenever and is instantly correct for all history because it is computed from marketing_leads on read, but the snapshot is the half that can never be recovered — a metric not captured today has no comparison tomorrow. Counters are CURRENT STATE (stage_id/outcome_id as the lead reads right now; outcome_id is overwritten when the lead moves on, so a lead that visited then converted leaves oc_visited_count and joins converted_count). Consumed by leads-service, which generates its SUM/INSERT/ON CONFLICT column lists from a single METRIC_KEYS list so the four declarations cannot silently drift; adding a KPI card or a grid column is now a UI-only change.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.43.0', 'Creating a user is now authorized by the lms.users.manage CAPABILITY evaluated per TARGET BRANCH, not by a rank-980 floor pinned to the session org. New iam.fn_user_can_manage_users(user, org) — modelled on iam.can_assign_to, resolving the role through iam.fn_user_org_role and the grant through iam.fn_role_capability_matrix, so SQL and @platform/db''s capability cache answer the question identically (tenant override > platform default > deny, and an ancestor resolving FALSE prunes its subtree). It returns TRUE unconditionally for org_admin/tenant_admin/super_admin, so no permission that existed before was removed. Five write policies moved off `iam.fn_user_org_rank(...) >= 980` onto it: org_admin_read/insert/update_policy on iam.user_org_mapping, users_org_write on iam.users, and org_admin_manage_policy on iam.reporting_lines (a create that supplies manager_id writes there too, so it had to move in the same step). Before this, granting lms.users.manage to a tenant-defined role was inert — the button appeared, identity-service''s rank>=40 gate passed, and the INSERT was refused by RLS as "new row violates row-level security policy", surfacing to the operator as a 403 they could only fix by handing out org_admin. The second half of the change is reach: each policy now tests `org_id = ANY(iam.fn_user_active_orgs(actor))` against THE ROW''S org_id rather than app.current_org_id, because iam.user_org_mapping is many-to-many — an actor mapped into several branches administers users in all of them without switching branch first. The tenant boundary is unchanged: every org in that array is one the actor holds a mapping row for, and tenant_isolation_policy still fences the tenant_admin pool. identity-service''s users.controller.create swapped its rank>=40 throw for the same capability check and resolveAssignments now validates each target branch against membership+capability instead of checkMoveUserBranchAccess''s platform_role test; the rank CEILING checks (canGrantRole, canManageUser) are untouched, since "who outranks whom" stayed a rank question. users_org_update on iam.users deliberately keeps the narrower org_id = current_org_id rule — editing an existing user across branches is a separate change. Existing databases: db_scripts/one_time/apply_user_create_capability_authz.sql.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.44.0', 'lead_assignment_weight moves off iam.user_org_mapping into lms.lead_assignment_weights, and iam.user_org_mapping gains a surrogate id for extension tables to key off. The column was pure LMS on the platform''s most shared table: only leads-service''s resolveAutoAssignedUser and its Python port in meta-sync-scripts ever read it, no SQL function/trigger/view touched it, and iam.vw_user_org_access did not even expose it — while iam.user_org_mapping is what iam.fn_user_active_orgs, the reporting-line membership check and most RLS policies are built on. Leaving it there meant every product wanting a per-branch, per-user setting would add its own column to that one table. The new shape is a reusable pattern rather than a one-off: iam.user_org_mapping.id (UUID, DEFAULT public.gen_uuidv7(), UNIQUE — NOT the primary key, which stays (user_id, org_id) so that every ON CONFLICT upsert in identity-service is unchanged and "one membership per user per branch" is still a PK guarantee), and product extension tables live in the OWNING product''s schema keyed by user_org_mapping_id ON DELETE CASCADE. lms.lead_assignment_weights is the first: no row means weight 0, which the picker already treats as out-of-rotation, so absence and an explicit zero are the same thing and only non-zero weights were backfilled. Because the extension table has no org_id of its own, RLS resolves it through a new SECURITY DEFINER helper iam.fn_mapping_org(mapping_id) — an inline subquery into iam.user_org_mapping would be re-filtered by that table''s own FORCE''d policies and return NULL, turning every extension policy silently FALSE instead of raising. Its four policies are org_admin_read/insert/update_policy and tenant_isolation_policy from iam.user_org_mapping with the row''s org_id replaced by that call, so the weight row is reachable exactly when its membership row is. lms.vw_lead_assignment_weights restores the flat (user_id, org_id, weight) shape the one_time/ and tools/ operator scripts query by branch. identity-service still owns every write (the user create/edit payload carries weights alongside branch/role, so the API contract and the UserForm are unchanged, field name included); leads-service only reads, via an INNER JOIN that subsumes the old weight > 0 filter. Also fixes moveUserBranch, which never handled weight at all — it left the source branch''s weight orphaned on the deactivated mapping and started the destination at 0. Existing databases: db_scripts/one_time/move_lead_assignment_weight_to_lms.sql.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.45.0', 'Capability namespace split, so the tenant admin console can gate its screens by permission instead of rank. `admin` was the PLATFORM OPERATOR namespace (lookup-admin: lookups, roles.manage) and unassignable to any tenant role — admin-service''s putGrants refuses it below super_admin, since admin.roles.manage DEFINES grants and would let a holder grant themselves anything. Meanwhile admin-web, the TENANT console, had no namespace at all: it borrowed platform.write for Team behind a rank-980 layout floor, so a role granted the directory capability still could not reach the screen. The operator keys move to a new `superadmin` root (iam.capabilities + @platform/rbac isSuperAdminCapability, renamed from isPlatformAdminCapability; the Capability Matrix now HIDES that subtree rather than rendering it locked, while putGrants keeps refusing it — the hide is an affordance, not the boundary). `admin` is re-created as the tenant console tool and takes two pages: admin.team (was lms.users — the directory manages fitness/HR/every user and is mounted outside the CRM) and admin.api_tokens (was platform.api_tokens — a console screen, so it sits with the console''s others; platform.* keeps only platform.write, which is behaviour everywhere rather than a screen). Renames, not aliases, per the platform.api_tokens precedent: exactly one name per capability. CRITICAL COUPLING: iam.fn_user_can_manage_users resolves ''admin.team.manage'' (was ''lms.users.manage'') and the ~9 write policies in 08_rls.sql call it, so the function and the grants must move in one transaction — anchor roles short-circuit to TRUE before the lookup, so only tenant-defined roles are exposed and only they prove the migration. Grants carry is_granted through unchanged so explicit denies survive, and every role holding an admin.* child is also granted the `admin` tool, without which the child resolves to nothing.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.46.0', 'New capability admin.team.notify (operation under admin.team), plus its default grant on org_admin and tenant_admin and a per-tenant back-fill pinned to admin.team.manage in reference_data/03_roles_and_grants.sql. It gates the "Notify user by email" checkbox on the Team create / reset-password / branch-change forms: identity-service''s users.controller checks it (hasCapability, alongside the existing rank>=ORG_ADMIN short-circuit) before users.service fires a fire-and-forget email through communication-service /api/v1/communications/public-send for user_created, password_reset_by_admin and branch/home-branch changes. Pure authorization for an outbound notification — NOT an RLS boundary, so unlike admin.team.manage it has no iam.fn_user_can_manage_users / 08_rls.sql coupling and stands alone. No table, column, policy, function or view change; this row exists only so a fresh db_deploy reports the same version as a server seeded incrementally. Existing databases: db_scripts/one_time/apply_admin_team_notify_capability.sql (idempotent INSERT ... ON CONFLICT of the node + grants).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.47.0', 'New notify schema and notify.push_subscriptions: Web Push subscriptions, one row per installed PWA + browser + device that has granted the Notification permission. Platform-wide on purpose, NOT under lms -- notifications-service is only the first consumer (follow-up due); hr-service (leave approved/rejected) and tasks-service (task assigned) are expected to follow, and a shared-tier schema is what keeps the second and third consumer from being a schema change. Same reasoning that put comms there. endpoint (the push service URL issued by the browser vendor) is the NATURAL KEY and is UNIQUE: the client re-registers on every launch -- deleting the Home Screen icon destroys the subscription and a fresh install issues a new endpoint -- so the subscribe path must be INSERT ... ON CONFLICT (endpoint) DO UPDATE or it accumulates one row per launch. p256dh/auth are the client public key and auth secret needed to encrypt a payload for that endpoint; user_agent is a debugging aid; last_used_at is stamped on each successful send so a pruning job can find registrations that went quiet without waiting for a 410. Rows are HARD-deleted (unsubscribe, and 404/410 Gone pruning) -- a dead device registration has nothing to audit, so the is_deleted/soft_delete_row recipe used by the domain tables is deliberately not applied. One index, (user_id, org_id): the sender lookup on every notification. RLS is ENABLE + FORCE with a DELIBERATE DEPARTURE from the org-only pattern every other table in 08_rls.sql follows -- the app_user policy constrains user_id AS WELL AS org_id. A push subscription is PERSONAL, not org-shared: with org isolation alone any colleague in the branch could SELECT the endpoint/p256dh/auth triple, which is everything needed to push a notification to that person''s locked phone, or DELETE the row and silently stop their alerts. tenant_isolation_policy stays tenant-scoped (same subquery shape as lms.lead_links) so an admin can prune dead registrations across branches. notifications-service reaches the table through root_service (DATABASE_URL_SERVICE / withServiceTx), which bypasses RLS because a send fans out to every device of the target user with no app session to scope it; the policies therefore guard incidental access from authenticated app sessions, the same reasoning already written above lms.lead_report_snapshot. Mirrored in @platform/db as notifySchema + pushSubscriptionsTable. Existing databases: db_scripts/one_time/apply_notify_push_subscriptions.sql (idempotent CREATE SCHEMA/TABLE IF NOT EXISTS + index, grants, RLS). This row originally shipped WITHOUT that script, and the omission is why every server seeded before 1.47.0 -- UAT and production alike -- had no table at all: db_scripts/00-10 are applied by Postgres'' init hook, which runs only on a database''s FIRST boot, so a later CREATE TABLE reaches a fresh db_deploy and nothing else. The symptom is total, not partial: POST /notifications/push/subscribe answers 500 with PostgresError 42P01 relation "notify.push_subscriptions" does not exist, no device can register, and no follow-up notification is ever delivered. It reads as device-specific because usePushSubscription''s mount reconciler swallows the identical failure on a browser that already granted permission, so only the handset where someone actually pressed Turn on reports an error.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.48.0', 'iam.users.email now has exactly ONE canonical spelling -- trimmed and lowercase -- on the way in, at every write path and in the login comparison. The column is a plain TEXT NOT NULL UNIQUE, and that UNIQUE is case-SENSITIVE, which produced two defects on the platform''s primary login credential: a user created as John.Doe@x.com could NOT sign in as john.doe@x.com (identity-service''s getUserByEmail is an equality test, u.email = $1, so a different casing matched no row and returned the generic invalid-credentials failure), and John.Doe@x.com plus john.doe@x.com could BOTH be created as separate accounts -- the UNIQUE did not collide, so asDuplicateUserConflict never fired and one person ended up with two identities, two sets of branch mappings and two audit trails. This is the same problem mobile solved when it became a login credential, and it is fixed the same way: new normalizeEmail() + emailInputSchema in @platform/validation (packages/platform-validation/src/email.ts) is the single normalizer, called by createUserSchema and updateUserSchema on the write path and by resolveLoginUser on the login path -- exactly where normalizeMobile() sits. One zod transform covers every writer because there IS only one: api-gateway proxies all /users writes to identity-service, /api/v1/public/users is GET-only, both consoles post to that same route, no other service writes the column, and there is no self-service signup, invite-accept, forgot-password or email-verification flow (admin reset is keyed by user id). New CONSTRAINT chk_users_email_lowercase CHECK (email = lower(email)) is the database half. A CHECK rather than citext (not enabled in this database, and an extension is a heavier answer than a constraint for one column) and rather than a UNIQUE INDEX on lower(email) (redundant once every stored value is already lowercase, and it would break the ON CONFLICT (email) upserts in dummy_data/): the CHECK makes an un-normalized writer -- an operator script, a psql session -- fail loudly at the point of the mistake instead of silently forking an identity. No index DDL changed; idx_users_org_email stays a plain-value index and becomes MORE useful, since an equality lookup on a guaranteed-lowercase column can now use it. normalizeEmail is deliberately case + whitespace ONLY -- no dot-stripping, no plus-tag removal, because those are provider-specific (Gmail) and would silently merge addresses that are distinct subscribers everywhere else. The audit target logged by auth.service on a failed login deliberately keeps the RAW identifier: it is the forensic record of what was actually typed, and audit.fn_detect_password_spray groups on it -- grouping is marginally looser across case variants, which is preferable to rewriting history. NOT fixed here, and still open: lms.marketing_leads.email and ext.meta_leads.email carry the identical case-sensitive dedup bug (uix_marketing_leads_org_email, and the AND email = $1 dedup in leads-service intake). Lead intake has its own dedup semantics and feeds the Meta CAPI hash, so it is a separate change. Existing databases: db_scripts/one_time/apply_email_lowercase.sql, which ABORTS with the offending rows listed if two live accounts (or a live and a soft-deleted one) differ only by case -- which row survives is an operational decision, not the script''s.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.48.1', 'ext.meta_page_form_org_map -- the table that decides which BRANCH every inbound Meta lead lands in -- becomes editable by a platform super_admin administering a SELECTED tenant, which is the shape the lookup-admin console uses everywhere else (?tenant_id= on the request, @platform/db withTenantConfigTx pinning app.current_tenant_id for the write). Until now the table was editable only by hand-written SQL or by meta-sync-scripts'' sync_forms.py::maybe_auto_map_form: a CRUD API existed in meta-conversion-api but was proxied by no gateway route, and every one of its four operations took tenant_id from the CALLER''s own gateway-injected headers -- so a super_admin listed their own tenant''s mappings (none) and would have written rows under the wrong tenant entirely. New admin_tenant_config_policy ON ext.meta_page_form_org_map, the same N-6 policy every other tenant-scoped config table carries. Without it the whole change reads ZERO ROWS AND RAISES NOTHING, because neither existing policy can serve that caller: org_isolation_policy is keyed on app.current_org_id, which withTenantConfigTx deliberately never sets (org_id = NULL = false), and tenant_isolation_policy is TO tenant_admin while the helper runs as app_user -- or, for a product-scoped login, as lms_svc, a NOINHERIT member of app_user reached only via the role-widening block at the foot of 08_rls.sql. The new policy keys on the table''s OWN tenant_id column and is deliberately NOT harmonised with tenant_isolation_policy''s entity.organizations subquery: the admin path is judged against the tenant it pinned, the tenant_admin path against org membership. The org_id half of its WITH CHECK is the security control, not boilerplate: tenant_id and org_id are independent columns here with NO trigger tying them together (none exists on this table in 04_functions_triggers.sql, and none is added -- the constraint belongs in the policy, where it also covers direct SQL), so without it a super_admin could pin tenant_id to tenant A and point org_id at tenant B''s branch, routing another tenant''s leads into a branch of their choosing -- the cross-tenant leak CLAUDE.md forbids outright. It is written as entity.fn_org_tenant(org_id) = <pinned tenant> rather than the inline `org_id IN (SELECT id FROM entity.organizations WHERE tenant_id = ...)` that the tenant_admin policies use, and that difference is load-bearing: a subquery inside a policy is re-filtered by the referenced table''s own RLS, and entity.organizations'' app_user policy is `id = ANY(iam.fn_user_active_orgs(current_user))` -- which returns NOTHING for a super_admin holding no membership in the administered tenant. The WITH CHECK would have been silently FALSE and every admin INSERT refused as a bare row-level-security violation. New entity.fn_org_tenant(UUID), STABLE SECURITY DEFINER, is that escape hatch, modelled exactly on iam.fn_mapping_org (1.44.0) and for the identical reason. Two GRANT gaps closed alongside, each of which would have surfaced as a permission error rather than a missing policy: app_user held only SELECT, INSERT on the table (a policy permitting a statement the GRANT does not is dead), and lms_svc -- which is what meta-conversion-api actually connects as -- held NOTHING on it, since ALTER DEFAULT PRIVILEGES IN SCHEMA ext covers only tables created after 07_grants.sql runs and this one is created in 02. DELETE is a real delete here: the table carries no is_deleted column and no soft_delete_row trigger. No table, column, constraint or index changed, so no one_time/ script is needed -- apply_schema.ps1 re-runs 04-08 and 10, which is every file this row touches. Numbered 1.48.1 rather than 1.49.0 so it does not collide with the campaign-type schema change queued behind it.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.49.0', 'Campaign TYPE becomes a first-class routing dimension: every inbound Meta lead used to be a SALES lead, auto-assignment picked from all weighted members of a branch, and there was one rotation per branch. The business now runs hiring campaigns alongside sales ones, and a hiring lead must land with the HR pool for that branch -- weighted within THAT pool -- and must not be visible to sales reps at all. THIS VERSION IS STRUCTURE ONLY: once backfilled, behaviour is byte-identical to 1.48.1. New marketing.campaign_types: a tenant-scoped lookup carrying department_id (the team the type routes to; NULL = visible to everyone), match_keywords, is_default and match_priority. tenant_id is NOT NULL and there are NO tenant_id IS NULL template rows, unlike the seven catalogs entity.seed_tenant_lms_catalogs() clones -- a template cannot carry department_id, which is the one column that makes a type mean anything, so the two starter types (`sales`, is_default, no keywords; `hiring`, department hr, keywords {hiring,hire,recruit,recruitment,hr,job,vacancy,trainer}, match_priority 50) are seeded as literals inside entity.seed_tenant_rbac() instead -- immediately after the departments they reference, which is also why they could not live in seed_tenant_lms_catalogs(), which runs first. It sits in the middle of the iam section of 02_tables_core.sql, not with the other marketing.* tables, because lms.lead_assignment_weights foreign-keys to it and a column-level REFERENCES is resolved at CREATE time. New ext.meta_campaigns is the SINGLE SOURCE OF TRUTH for campaign -> type, shaped on ext.meta_forms: tenant-scoped, no org_id, the natural Meta id carrying the UNIQUE. The mapping lives in ext rather than on marketing.ad_campaigns because ad_campaigns.org_id is NOT NULL -- a CRM campaign row is per BRANCH, while a Meta campaign is not branch-scoped (only its leads are) and a proactive fetch from an ad account has no branch to attribute to at all. Putting it here means an admin confirms a campaign''s type ONCE, not once per branch. uq_meta_campaigns_campaign_id is deliberately GLOBAL, not (tenant_id, meta_campaign_id): Meta ids are globally unique and one row must serve every branch, exactly as ext.meta_forms treats form_id. Do not ''fix'' it. mapping_status drives three admin grids in a later phase -- suggested (a keyword matched, matched_keyword says which), unmapped (nothing matched, pick by hand), confirmed (done). A confirmed mapping must NEVER be overwritten by a later fetch or sync: every writer has to exclude it explicitly, because an inferred type is provisional and an admin''s decision is not. Five altered tables: ext.meta_tenant_config.ad_account_ids TEXT[] (the accounts a later Fetch Campaigns button iterates -- a column and not an ext.meta_ad_accounts table, because an ad account carries nothing but its id here, pages are already handled the same way with a bare page_id and no ext.meta_pages, and the only per-campaign sync state there is lives on ext.meta_campaigns.last_synced_at); marketing.ad_campaigns.campaign_type_id (the per-branch projection only -- the provisional/confirm workflow columns stay on ext.meta_campaigns); lms.marketing_leads.campaign_type_id, DENORMALISED on purpose because a lead can carry a type with no campaign at all and because the RLS predicate reads it per row, where a nullable join would be slower and harder to reason about; ext.meta_page_form_org_map.default_campaign_type_id, the fallback when a campaign name matches nothing and the ONLY signal for a lead carrying no campaign id whatsoever; and lms.lead_assignment_weights.campaign_type_id NOT NULL, whose PRIMARY KEY becomes (user_org_mapping_id, campaign_type_id). Pool membership is now PER TYPE: the same person can sit in their branch''s sales rotation at 40% and its hiring rotation at 0%. That table still has NO org_id -- the branch resolves through iam.fn_mapping_org(mapping_id), per the 1.44.0 note -- so any per-(branch, type) query must go through iam.user_org_mapping and not a direct column. one_time/move_lead_assignment_weight_to_lms.sql contains a second, now-stale CREATE of that table and was DELIBERATELY LEFT ALONE: it is the historical record of an already-applied change, not a live definition, and editing it would rewrite what actually ran on those servers. Three new functions. marketing.fn_match_campaign_type(tenant, name) -> type id, STABLE, matches keywords case-insensitively on WORD BOUNDARIES (lowest match_priority wins, sort_order then name break ties, NULL when nothing matches). It is in SQL specifically so the TypeScript intake path and msq-lms/meta-sync-scripts'' Python port cannot drift on what ''a hiring campaign'' means -- sync_campaigns.py carries a comment about that exact hazard. It does NOT use Postgres'' \m/\M word-boundary escapes: those treat _ as a word character, and Meta campaign names are overwhelmingly underscore-separated (''HIR_Gurugram_Trainer_Sep26''), so \mtrainer\M would never fire; the predicate requires a non-alphanumeric or the string end on both sides instead. Not SECURITY DEFINER, deliberately: definer rights would let an app_user session probe another tenant''s keywords by passing a foreign tenant id. lms.fn_user_sees_campaign_type(user, org, type) -> boolean, STABLE SECURITY DEFINER, is the visibility decision: TRUE when the type is NULL, WHEN THE TYPE IS THE TENANT''S DEFAULT, when the type has no department_id, for the three anchor roles, when the role holds lms.leads.view.all_types, or when the role''s department matches the type''s. The is_default clause is load-bearing and was added after testing, not designed in: iam.user_roles.department_id was passed as a literal NULL by entity.seed_tenant_rbac() from the day Tier C shipped, so EVERY role in EVERY tenant is department-less, and without that clause the instant the backfill committed a read_only auditor and every un-wired ladder role would have lost the entire pipeline -- the backfill stamps `sales` on all of it. The default type is the catch-all (unmatched campaigns, walk-ins, manually created leads all land there), so making it universally visible is also what the column means. The boundary being drawn is "keep HIRING leads away from sales", not "fence the general pool off from anyone lacking a department". The role-department gap is fixed properly alongside: seed_tenant_rbac() now resolves department_id by name when it clones the ladder (sales_representative / senior_sales_executive / org_manager / org_sr_manager -> sales, hr_admin -> hr; the four anchors stay department-less because they are cross-department by definition and reach every type by capability instead), and the backfill script wires up existing tenants'' copies with a COALESCE so a tenant that already repointed a role keeps its choice. That column could never have been cloned from the template: template roles are global (tenant_id IS NULL) while iam.departments is tenant-scoped. Until this version nothing read the column, so populating it is additive -- iam.fn_user_org_role''s `department` return value simply stops being NULL, and no service branches on it. It asks iam.fn_user_org_role and iam.fn_role_capability_matrix rather than reading iam.role_capabilities directly, for the reason iam.fn_user_can_manage_users already documents: only the matrix implements BOTH resolution rules (tenant override > platform default > deny, AND an ancestor resolving FALSE pruning its subtree), so a raw lookup would let SQL and the application''s capability cache disagree about one grant. SECURITY DEFINER because it is called from inside a policy and reads RLS-protected iam.* and marketing.* -- invoker rights would be filtered by those policies and return NULL rather than raise, turning the predicate silently FALSE and hiding EVERY typed lead from EVERYONE. It fails OPEN for an unknown type id, which leaks nothing: the predicate only narrows an already org-scoped result set, so failing closed would hide a branch''s own rows over a data error. lms.sync_lead_campaign_type() is a BEFORE INSERT OR UPDATE OF campaign_id trigger on lms.marketing_leads that copies the campaign''s type down when none was supplied, keeping the denormalised column honest when a campaign is attached late from the UI or a batch script; it never overwrites a type set explicitly in the same statement, which is what lets a manager reclassify one lead without the next campaign edit undoing it. lms.log_lead_assignment() now appends the pool label to the note and writes a new ''reclassified'' action when the type moved in the same statement -- so chk_assignment_action on lms.lead_assignment_log gained that value. RLS IS THE SALES/HR BOUNDARY, and this is the security core of the change. Both lms.marketing_leads policies gained lms.fn_user_sees_campaign_type(current_user_id, org_id, campaign_type_id) on USING -- and ONLY on USING. WITH CHECK was deliberately NOT narrowed: it governs writes, and a manager legitimately creates and reassigns leads across types (that is what reclassification IS). Narrowing it would hide not one extra row and would only stop managers routing work, with a bare ''new row violates row-level security policy'' naming nothing. Because the function returns TRUE for a NULL type, adding the term changes nothing until the backfill runs. marketing.campaign_types and ext.meta_campaigns each get org_isolation_policy (SELECT, tenant derived from the session''s current org -- an app_user sets app.current_org_id and never app.current_tenant_id), tenant_isolation_policy, and the N-6 admin_tenant_config_policy for a super_admin administering a selected tenant through withTenantConfigTx. The NOINHERIT service logins are not named in those policies by hand because the widening block at the foot of 08_rls.sql rewrites every policy''s role list from current membership; GRANTs have NO such block, which is why 07_grants.sql names lms_svc, lead_svc and meta_svc explicitly on both new tables and both new functions. Getting that wrong is the failure this repo has been bitten by twice: ZERO ROWS AND NO ERROR. Note in particular that EVERY role which reads a lead needs EXECUTE on lms.fn_user_sees_campaign_type, because it is evaluated inside that table''s own policy. Views: lms.vw_dashboard_leads gains campaign_type_id / campaign_type / campaign_type_label, APPENDED at the end because CREATE OR REPLACE VIEW cannot insert a column mid-list, and sourced from the LEAD''s own column rather than the campaign''s so it cannot show a different answer than the one visibility was decided on. (There is no view named marketing_leads_vw in this database and never has been -- only a stale mention in a comment above marketing.ad_campaigns; the lead listing is lms.vw_dashboard_leads.) lms.vw_lead_assignment_weights gains the type columns and IS NO LONGER ONE ROW PER (user, branch): it is one row per (user, branch, type), plus a NULL-type row for a membership in no rotation at all. Any caller assuming uniqueness on user_org_mapping_id must add a type filter. Indexes: uix_campaign_types_one_default, a PARTIAL UNIQUE on (tenant_id) WHERE is_default AND NOT is_deleted, because two defaults is not cosmetic -- the default is what the backfill, the intake fallback and the admin UI all resolve to, so a second one is a silently non-deterministic routing rule; idx_meta_campaigns_tenant_status for the three admin grids; idx_marketing_leads_org_campaign_type; idx_ad_campaigns_campaign_type; idx_meta_campaigns_campaign_type; and idx_lead_assignment_weights_type, which the picker needs because the new composite PK leads on user_org_mapping_id and cannot serve ''who is in this type''s pool''. Capabilities: lms.campaign_types (page) + .view + .manage mirroring lms.campaigns, and lms.leads.view.all_types. That last one is declared kind=''operation'', NOT kind=''scope'', despite its key reading like a scope -- and the distinction is load-bearing. For a scope node sort_order IS the breadth ordering (effective scope is the granted sibling with the highest sort_order; see iam.capabilities'' own comment and resolveScope() in @platform/rbac), so a fifth child on the own/team/org/tenant ladder would outrank ''whole branch'' and silently REPLACE a manager''s row scope. Campaign-type visibility is an orthogonal axis, not a wider rung: a rep holding it plus .own still sees only their own leads, of every type. It is granted to org_manager, org_sr_manager, org_admin and tenant_admin and deliberately NOT to sales_representative, senior_sales_executive or read_only. The per-tenant back-fill pins it to lms.leads.delete rather than the more obvious lms.leads.view.org, because the audiences differ by one role that matters: read_only holds view.org, and an audit account seeing the branch should not thereby start seeing HR''s hiring pipeline -- the holders of lms.leads.delete are exactly the four roles intended. lms.campaign_types is added to the nav-DENY list for read_only, sales_representative and senior_sales_executive alongside lms.campaigns: a page with no row at all INHERITS its parent''s grant, so omitting it would REVEAL the page rather than hide it. Verify all of this with iam.fn_role_capability_matrix, never by reading iam.role_capabilities, which shows grant rows that a denied ancestor renders inert. Existing databases: db_scripts/one_time/apply_campaign_types.sql (DDL -- both tables, all five columns, the CHECK, indexes, grants, RLS, AND the four capability nodes with their role grants. The capabilities are in that script and not left to reference_data/ because apply_schema.ps1 re-runs 04-08 and 10 only and never touches reference_data -- "data, not schema" -- while 00-10 and reference_data run only on a database''s FIRST boot. Without them an existing server keeps the repo''s capability tree and the database''s old one, and the failure is silent in the worst direction: org_manager and org_sr_manager hold no lms.leads.view.all_types, so the day a campaign is typed `hiring` its leads disappear from the manager''s list with no error anywhere. Verified on a restored pre-1.49.0 database: before the capability block was added, a manager saw 20 of 30 leads; after, 30) and db_scripts/one_time/backfill_campaign_types.sql (data -- the two seed types per tenant, ext.meta_campaigns seeded from the historical DISTINCT ext.meta_leads.campaign_id back-catalogue so an admin''s first fetch is not the first time they see their own campaigns, and the four column backfills), each with a read-only _dryrun.sql twin. The PK swap lives in the BACKFILL script, not the apply script. ORDER MATTERS: the weight rows must be populated with campaign_type_id BEFORE the column is made NOT NULL and before the primary key is replaced; doing the PK first fails on every existing row. Both scripts are needed because apply_schema.ps1 re-runs only 04-08 and 10 -- it never re-runs 02/03, which are CREATE TABLE IF NOT EXISTS and would no-op on a populated database. 1.47.0 above is the post-mortem of the last time that step was skipped. After the backfill, SELECT assigned_user_id, count(*) FROM lms.marketing_leads GROUP BY 1 must be unchanged and every pre-existing weight row must reappear under its tenant''s `sales` type with the same weight. The backfill SUPPRESSES trg_marketing_leads_updated_at / trg_marketing_leads_audit and trg_ad_campaigns_updated_at / trg_ad_campaigns_audit around its two type UPDATEs (DISABLE/ENABLE TRIGGER inside its transaction): stamping a structural default is not an edit, and leaving them on moved every lead''s updated_at to migration day and wrote one audit row per lead and per campaign. updated_at and the audit log are therefore a true no-op too.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.50.0', 'Meta lead PULL moves off a developer''s laptop and into the console, and the platform gains its first STAGING schema to hold it. Leads arrive from Meta via the live webhook, but webhooks miss things -- an integration that was down, a page mapped late, a form nobody knew about -- and until now the only remedy was a three-stage Python CLI (meta-sync-scripts: download_page_leads.py -> check_leads_against_db.py -> import_downloaded_leads.py) run by hand against output/<run>/ CSVs. This version is the schema half of replacing that with a super-admin screen: choose orgs/pages/campaigns and a start date, pull, see exactly what is genuinely missing from LMS versus already present, and apply only the missing ones. New `scratch` SCHEMA. A schema rather than more ext.* tables because the LIFECYCLE is the opposite of everything in ext: these rows exist to be reviewed and thrown away, are DELETEd wholesale rather than soft-deleted, carry no is_deleted/deleted_at/metadata columns and no soft_delete_row trigger, and nothing downstream may foreign-key into them. Putting them under a name that says `scratch` is what makes "this table is disposable" readable without finding a comment. scratch.meta_pull_runs IS THE QUEUE. There is no job/queue infrastructure in this repo -- verified: no bullmq, pg-boss, agenda, node-cron, Redis or worker process -- and the only background pattern is notifications-service''s setInterval poller with a `running` overlap guard (followup-checker.ts), so a queue table and a poller is what was built rather than new infrastructure. POST /meta/lead-pull/runs inserts status=''queued'' and returns run_id in one fast transaction, so nothing rides on the gateway timeout; a poller in meta-conversion-api claims work with SELECT ... WHERE status=''queued'' ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1. Compose runs one instance today, but SKIP LOCKED means adding a replica later does not double-run a pull -- and the in-process boolean guard does not survive replicas, so both are used. heartbeat_at (written per page completed) plus a REAPER that fails runs whose heartbeat has gone stale is the whole reason for a claimed queue rather than a floating promise: POST /runs refuses with 409 while a run is queued/running/applying, so a deploy mid-pull would otherwise strand the run in ''running'' forever and that tenant could never start another one. scratch.meta_pull_leads holds one row per lead Meta returned, with three column groups: the raw lead (page_id, form_id, form_name, meta_lead_id, campaign_id, adset_id, ad_id, platform, lead_created_at, raw_field_data -- shaped to map 1:1 onto syncLeadToDatabase''s RawMetaLead parameter, which is what Apply calls); the classification (verdict, existing_lead_id, reason); and the apply outcome (applied_status, applied_lead_id, applied_error). UNIQUE (run_id, meta_lead_id) because Meta pages the same lead across cursor pages more often than its docs admit, so the staging insert is ON CONFLICT DO NOTHING. ORG_ID IS NULLABLE HERE, unlike ext.meta_page_form_org_map where it is NOT NULL, and that is deliberate rather than an inconsistency to fix: a staged row with NO org IS the `unmapped_form` verdict -- a lead Meta returned for a form nobody has mapped. It is recorded so the admin can see it and go fix the mapping, and Apply skips it with that reason; it can never be applied. ONE DELIBERATE BEHAVIOUR CHANGE FROM THE PYTHON, called out because it alters what gets imported: `hiring_form` was a SKIP verdict in common/reconcile.py, because there was nowhere to route a job applicant -- recruitment forms share the Pages that carry sales campaigns. After the campaign-type work in 1.49.0 there IS somewhere, so hiring_form stops being a verdict at all and becomes two columns, is_hiring_form and suggested_campaign_type_id (resolved through marketing.fn_match_campaign_type on the form NAME, which is why form_name is staged). The lead now classifies and imports normally and the admin is told the form looks like recruitment and which type it would match -- the fix being to set ext.meta_page_form_org_map.default_campaign_type_id, the signal syncLeadToDatabase already reads. Leads on hiring forms that were previously discarded will therefore now be imported. The remaining seven verdicts are ported from reconcile.py::classify() verdict for verdict AND IN ORDER: already_synced (ext.meta_leads.meta_lead_id) - test_lead (/test lead:/i, the Lead Ads Testing Tool placeholder) - unmapped_form - missing_contact - phone_duplicate (last TEN significant digits, right(regexp_replace(phone,''\D'','''',''g''),10), so a number already on file in another format is found) - email_duplicate - new. IMPORTABLE stays {new, phone_duplicate, email_duplicate}: the two duplicate verdicts are importable ON PURPOSE, because the canonical write path supersedes on phone and returns the existing lead on email, and either way an ext.meta_leads row gets written -- which is what stops the lead being re-fetched forever. Dropping them would make every future pull re-surface the same leads. RLS: ONE policy per table, admin_tenant_config_policy FOR ALL TO app_user keyed on app.current_tenant_id -- the N-6 admin shape, because this is a platform super_admin administering a SELECTED tenant through @platform/db''s withTenantConfigTx, which pins app.current_tenant_id and app.current_user_id and sets app.current_org_id NOT AT ALL. An org-keyed policy would evaluate org_id = NULL -> false and read ZERO ROWS WITH NO ERROR, the failure shape this repo has been bitten by twice. There is deliberately no org_isolation_policy and no tenant_isolation_policy: no ordinary app_user session and no tenant_admin session ever touches these tables, and tenant_admin is not granted DML either, since a grant with no policy buys nothing but the impression of access. Tenant isolation is the POLICY and never a literal WHERE tenant_id = $1 in the service -- a filter alongside the policy would make the cross-tenant test pass whether or not the policy works. The org_id half of scratch.meta_pull_leads'' WITH CHECK is a security control lifted from ext.meta_page_form_org_map for the identical reason: tenant_id and org_id are independent columns with no trigger tying them, and APPLY WRITES REAL LEADS INTO WHATEVER ORG THE STAGED ROW NAMES, so without it a row could name tenant A while pointing org_id at tenant B''s branch. It is written `org_id IS NULL OR entity.fn_org_tenant(org_id) = <pinned tenant>` -- NULL admitted because that is the unmapped_form verdict, and fn_org_tenant rather than an inline entity.organizations subquery because such a subquery is re-filtered by that table''s own membership-keyed app_user policy and returns nothing for a super_admin holding no membership in the administered tenant (1.48.1 documents this at length). GRANTS: DELETE IS GRANTED, WHICH BREAKS 07_grants.sql''s NO-DELETE CONVENTION ON PURPOSE. Every other service grant in that file is SELECT/INSERT/UPDATE because a domain row is soft-deleted and a real DELETE is a bug; these tables have no is_deleted column, and POST /runs BEGINS by deleting the tenant''s previous run so nothing from the last pull survives into the next (the FK cascade takes the staged rows). Without DELETE the feature''s first statement fails. Named for lms_svc -- the login meta-conversion-api actually connects as (DB_LMS_SVC_USER with DB_PRODUCT_SCOPED_LOGIN=true, so withTenantConfigTx runs AS lms_svc and never does SET ROLE app_user) -- and for meta_svc, which meta-sync-scripts uses; `TO app_user` alone reaches neither, because every *_svc login is NOINHERIT and GRANTs have no equivalent of 08_rls.sql''s policy-widening block. Five indexes: (tenant_id, status) for the 409 guard and the clearing DELETE, two PARTIAL indexes for the poller claim (WHERE status=''queued'') and the reaper (WHERE status IN (''running'',''applying'')) since the queue is empty almost all of the time, and (run_id, verdict) / (run_id, applied_status) for the summary, its drill-down and the apply worklist. Two Meta constraints are designed WITH rather than around, and both are visible in the API contract: there is NO CAMPAIGN-SCOPED LEAD EDGE (leads come page -> /{page-id}/leadgen_forms -> /{form-id}/leads and campaign_id is only a FIELD on each lead), so a campaign filter is POST-FETCH and narrowing campaigns cannot make a pull faster or cheaper -- the run''s `filters` JSONB records this verbatim so the screen can say so, rather than letting an admin read a slow single-campaign pull as a bug; and Meta IGNORES the `time_created` filter, so `since` is sent as an optimisation and ALWAYS re-applied client-side, keeping leads whose created_time is unparseable rather than dropping them, exactly as graph_api.py::in_window does. `since` is REQUIRED by the request schema even though the Python defaults it: an unbounded pull across every page of a large tenant is precisely the operation that will hit Meta throttling from a button press. Existing databases: db_scripts/one_time/apply_scratch_lead_pull.sql, with a read-only _dryrun.sql twin. It is needed because apply_schema.ps1 re-runs only 04-08 and 10 and never 02/03 (CREATE TABLE IF NOT EXISTS would silently no-op on a populated database), so a new schema and two new tables would otherwise reach a fresh db_deploy and nothing else -- 1.47.0 above is the post-mortem of the last time that step was skipped.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.50.1', 'lms.lead_assignment_weights can no longer pair a membership with a campaign type from ANOTHER tenant. New trigger trg_lead_assignment_weights_tenant_match (BEFORE INSERT OR UPDATE OF user_org_mapping_id, campaign_type_id) calls new lms.fn_assert_weight_type_tenant(), which resolves the membership''s branch tenant and the type''s tenant and raises check_violation when they differ. WHY: the table''s composite PK and both FKs are satisfied by a type from any tenant, and identity-service validated a weight''s campaign_type_id against the ACTOR''s tenant rather than the target branch''s. For a platform super_admin in lookup-admin''s OrgAccessPanel -- which spans every tenant''s branches, and which leads-service''s /campaign-types (then ignoring ?tenant_id=) fed THE SUPER ADMIN''S OWN tenant''s types -- that wrote weight rows pointing at a foreign type into another tenant''s branch. Such a pool routes nothing, because resolveAutoAssignedUser joins on the lead''s own tenant''s type id: a user who looks weighted is simply never picked, the silent-null failure 1.44.0 and the 10-of-30-branches incident already cost this platform once. Fixed in three places, deliberately overlapping: identity-service addOrgMapping now validates role and type against the TARGET BRANCH''s tenant and refuses a non-super-admin granting into a branch of another tenant (orgExists alone had accepted any branch on the platform); leads-service /campaign-types honours ?tenant_id= for a platform super_admin; and this trigger, so a missed check in any writer -- a service, a batch script, psql -- is a refused statement instead of a corrupt row. Resolves the branch tenant directly rather than through entity.fn_org_tenant, which filters NOT is_deleted, so a weight on a membership of a since-deleted branch can still be zeroed. SECURITY DEFINER because the writers'' own RLS on iam.user_org_mapping (FORCE RLS), entity.organizations and marketing.campaign_types would hide the compared rows and refuse valid writes. A trigger does NOT re-validate rows already on disk: run db_scripts/one_time/audit_cross_tenant_weights_dryrun.sql (read-only) on every server once; any row it lists is an operational clean-up (delete, or re-point at the branch tenant''s same-named type, which the report includes). Function + trigger only, in 04 -- apply_schema.ps1 re-runs it, so no apply one_time script is needed. Same version, same class of silent mis-route: new marketing.fn_campaign_type_usage(UUID), STABLE SECURITY DEFINER, counts ext.meta_campaigns rows mapped to a type and active ext.meta_page_form_org_map rows defaulting to it. Deactivating a type that a campaign was still mapped to used to FAIL INTAKE for every new lead on that campaign (leads-service refuses an inactive type, meta-conversion-api forwarded it anyway); both services now fall back to the form/tenant default instead, and leads-service''s PATCH is_active=false and DELETE on /campaign-types refuse with 409 while either count is non-zero, so a pool cannot be retired out from under live routing without re-pointing it first. A function rather than a grant because leads-service never reads ext.*. EXECUTE granted to lms_svc, lead_svc, tenant_admin and root_service by name. Also in this version: scratch.meta_pull_runs.status gains ''apply_queued''. POST /meta/lead-pull/runs/:id/apply used to do the whole Apply INLINE -- one leads-service intake call per staged row -- behind a gateway that abandons a proxied request after 30 seconds, so any real Apply answered 504 while the server kept writing, the screen re-enabled the button, and a second press got 409. The route now only moves completed -> apply_queued and returns 202; the existing lead-pull poller claims it (FOR UPDATE SKIP LOCKED, apply_queued -> applying), heartbeats every 25 rows, and the screen polls GET /runs/:id. An interrupted or erroring Apply now returns the run to COMPLETED rather than FAILED, because every applied row is recorded and the rest are still pending, so pressing Apply again resumes -- a failed run could never be applied again and forced a full re-pull. The poller claim index is replaced: idx_meta_pull_runs_queued (pulls only) is dropped for idx_meta_pull_runs_claimable over both queued statuses, under a new name because CREATE INDEX IF NOT EXISTS cannot change an existing index''s predicate. The new meta-conversion-api image writes ''apply_queued'', so the one_time script must run BEFORE that image is deployed. CHECK and index changes need db_scripts/one_time/alter_scratch_apply_queued.sql (+ _dryrun.sql) on existing servers, because apply_schema.ps1 never re-runs 02.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.50.2', 'Lead-assignment weights are bound to the user''s DEPARTMENT (product decision 2026-09-13): a weight is valid only for a campaign type whose department_id equals the department of the membership''s role, and a role with no department cannot be weighted at all. WHY: lms.fn_user_sees_campaign_type already shows a typed lead only to a role in the type''s department (or holding lms.leads.view.all_types), but nothing stopped a Sales rep being weighted for Hiring -- the picker would then auto-assign hiring leads that RLS hides from their owner. Enforced in four places: lms.fn_assert_weight_type_tenant (the 1.50.1 trigger) now also refuses a NEW row whose type department differs from the role''s, or whose role has no department; identity-service validates create/edit user, org-mapping grants and PUT /users/assignment-weights with a 400 naming the role; the user forms offer only the role department''s campaign types; and the picker (leads-service assignment.ts, reclassify condition 4, meta-sync-scripts lead_writer.py) counts a weight only when the departments match, returning the new reason no_department_match. EXISTING rows that break the rule are deliberately KEPT, not moved or deleted: the trigger lets an upsert of an already-held (membership, type) row through, the picker skips them, and one_time/report_weight_department_mismatch_dryrun.sql lists them. Leads that would have gone to those people arrive unassigned with reason no_department_match; once an admin fixes the role''s department or the weights, lookup-admin''s new Re-run Auto-Assignment action (leads-service POST /lead-assignment/rerun, super_admin only, dry run first, 500 leads per call) assigns them -- only leads with no owner and no logged interaction, never moving a lead away from a person. No seeded role changes: hr_admin still has no LMS access, so the Hiring pool routes nothing until a tenant creates an HR-department role with LMS capabilities. Function-only DB change (04), picked up by apply_schema.ps1; no apply one_time script needed.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.51.0', 'Meta lead routing is made correct end to end: a lead lands in the right tenant and branch (from its PAGE) and the right department (from its campaign TYPE), and the console can manage every input to that decision. ORDERED RULES REPLACE KEYWORDS. New marketing.campaign_type_rules (tenant_id, rule_order, match_field in campaign_name/form_name/adset_name/ad_name, pattern, campaign_type_id), FIRST MATCH WINS in rule_order, same word-boundary predicate as before. match_keywords hung off each type could only say "this TYPE beats that one", never "this PHRASE beats that one" (PT_Sale must beat trainer). New marketing.fn_match_campaign_type_rules(tenant, campaign, form, adset, ad) returns (campaign_type_id, rule_id, match_field, pattern); fn_match_campaign_type becomes a campaign-name-only wrapper over it; match_keywords is no longer read (kept one version). trg_campaign_type_rules_tenant_match refuses a rule pointing at another tenant''s type. Existing keywords convert to campaign_name rules in their old precedence (match_priority, sort_order, name) EXCEPT the pre-1.51.0 seeded hr, job and trainer, which match fitness SALES campaign names; 10_tenant_provisioning seeds rules, not keywords. THE FIRST LEAD NO LONGER FIXES A CAMPAIGN''S TYPE. ext.meta_campaigns.campaign_type_id is now set only by an admin confirm; the engine''s guess lives in new suggested_campaign_type_id + matched_rule_id. Before, an unmatched or unnamed new campaign stored the form/tenant FALLBACK (usually Sales) as its type and every later lead inherited it -- a hiring campaign whose name lookup failed stayed Sales forever. Backfill moves every non-confirmed row''s campaign_type_id into suggested_campaign_type_id. Type precedence on every intake path: confirmed campaign type, then rules evaluated per lead, then the page/form default type, then the tenant default. INTAKE-ASSIGNED LEADS ARE NOW LOGGED: new trg_lead_assignment_log_insert writes an ''initial'' lms.lead_assignment_log row for a lead inserted with an owner (the trigger was UPDATE-only, so campaign reclassification -- which keys on that row -- never saw intake-assigned leads and left them with an owner who, after a re-type, could no longer see them). Backfill writes the missing ''initial'' rows. New lms.marketing_leads.auto_assign_reason records WHY a lead has no owner (no_campaign_type, no_weighted_users, no_department_match, no_capable_users) instead of a log line only. SHARED-APP CAMPAIGN DISCOVERY: new ext.meta_ad_accounts (platform-level, root_service only, RLS on with no policy) lists every ad account the shared token sees, with an enable flag the fetch honours; ext.meta_campaigns gains page_ids (the pages its ad sets promote) and conflict_reason, and the fetch attributes each campaign to the ONE tenant its pages map to -- before, it inserted every campaign under whichever tenant pressed Fetch. ext.meta_tenant_config.ad_account_ids is deprecated. New ext.meta_adsets and ext.meta_ads cache the names the per-lead rules match on. LOST LEADS LEAVE A TRACE: new ext.meta_lead_inbox holds webhook leads that did not become an LMS lead (unmapped page, missing contact, sync failure) with their field data, for a super admin to map and Retry; before they were a log line and, because the webhook answers 200, Meta never redelivered them. tenant_id NULL rows match no policy (super-admin service path only); tenant rows get the N-6 policy with the fn_org_tenant org check. scratch.meta_pull_runs gains trigger_kind (manual/scheduled) so the scheduled catch-up pull never clears a run an admin is reviewing. ext.meta_forms gets the N-6 admin policy (the console form picker writes it). Existing databases: db_scripts/one_time/apply_meta_routing_1_51.sql (+ _dryrun.sql) for the tables, columns and backfills, then apply_schema.ps1 for 04-08 and 10.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.51.1', 'Strict department separation of leads (product decision 2026-09-27: Sales sees sales leads, HR sees hiring leads). lms.fn_user_sees_campaign_type no longer shows the tenant''s DEFAULT campaign type to everyone: a role that sits in a DIFFERENT department from the default type (e.g. an HR-department role, default = Sales) now sees it only if it is an anchor role or holds lms.leads.view.all_types. A role with NO department (read_only, org_admin, tenant_admin, super_admin, or a ladder role whose department was never wired) still sees the default, so no auditor or unwired role loses its branch. Sales-department roles are unaffected. Untyped leads and department-less types stay visible to all, as before. WHY: until now only half the boundary existed -- hiring leads were kept off sales screens, but the whole sales pool was on every HR screen. Auto-assignment has been department-bound since 1.50.2, so routing and visibility now agree. The function also resolves the role''s department BEFORE the capability matrix, so the default-typed majority of rows settles on one indexed lookup. Same version, application side: the Leads page type filter moved into the LMS navbar and is gated on lms.leads.view.all_types (no new capability); leads-service applies campaign_type_ids on GET /leads and GET /leads/follow-ups only for holders of that capability, and GET /campaign-types (list) also admits it. Function-only DB change (04), picked up by apply_schema.ps1. Before deploying, run db_scripts/one_time/report_default_type_fence_dryrun.sql (read-only) to list the roles and open default-type leads that will leave a user''s view.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.52.0', 'New attendance status missed_punch, and a detailed attendance report (product decision 2026-09-28). A day with a check-in that was never closed by a check-out used to stay PRESENT forever: resolveEventStatus returned a tentative present for an open session, the live punch wrote that row, and the nightly resolve-attendance job only fills days that have NO row, so nothing ever revisited it -- it counted as present on the payroll summary. Now ANY unclosed check-in (trailing, or abandoned by a later check-in) on a FINISHED work day resolves the whole day to missed_punch, whatever the closed sessions add up to: not present, not paid, until the employee regularizes it. The closed sessions'' minutes stay in worked_minutes for the audit trail. A day is finished once the org-local date has moved past it, or for a night shift once the next morning reaches the shift end (hr-service lib/attendance/time.ts isDayFinished); until then the live punch keeps writing the tentative present, so today''s dashboards are unchanged. The nightly job gains a finalize pass over punch-resolved days in its lookback window that still hold an open session, re-deriving them from their punches alone (resolveFromEvents), so a check-in on a holiday or weekly off is finalized too rather than re-resolved to weekly_off. Regularized days are never touched. hr.attendance_statuses catalog v2 (reference_data/07_catalog_registry.sql) adds missed_punch for new tenants; hr.vw_attendance_monthly_summary gains missed_punch_count, appended LAST because CREATE OR REPLACE VIEW can only add trailing columns. hr-service writes fall back to absent (also unpaid) for a tenant that has no missed_punch row yet, rather than failing the NOT NULL status_id insert and with it the job for every tenant. Same version, application side: GET /attendance/reports/detail (gateway /hr/attendance/reports/detail), gated like the summary on hr.attendance.admin.reports.view plus hr.attendance.admin -- no new capability. xlsx has Summary / Daily Detail (every roster employee x every date up to today: status, holiday, leave type and half, shift, first in / last out, every session, worked, late, early exit, WFH, regularization) / Punches (one row per check-in -> check-out session; punches withheld by face review listed as not counted); csv is the Daily Detail sheet. Sessions are paired by the same pairSessions the day classifier uses. The Reports tab Download now serves it and the on-screen table shows Missed Punch. Existing databases: db_scripts/one_time/apply_missed_punch_status.sql (+ _dryrun.sql) adds the status to every tenant, registers catalog v2 and backfills finished open days up to the day before yesterday (org-local; the nightly job finalizes yesterday so a running night shift is not flipped), then apply_schema.ps1 for the view. ALSO IN 1.52.0 (gaps found while building the report): (1) the job marked EVERY day of a leave half_day when the leave merely started or ended on a half -- only the leave''s own first/last day can be a half now (isHalfLeaveDay); (2) the job resolved days before date_of_joining / after date_of_exit, writing them as absent -- it now clamps its window to employment, and the report shows those days as Not Employed; the one_time script corrects both kinds of existing rows (full leave days back to on_leave; job-computed rows outside employment deleted -- never rows with punches, leave or a regularization); (3) vw_attendance_monthly_summary.wfh_count was always 0 because nothing sets the wfh status -- it now also counts days with a counted WFH punch inside first_in..last_out, overlapping present by design, as getTodaySummary already did; (4) api-gateway never proxied GET /hr/leave/requests/:id or GET /hr/attendance/regularizations/:id though hr-web calls both, so those detail views 404''d; (5) the My Attendance day popover offered Request regularization only for absent / not_marked / half_day -- missed_punch added.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.53.0', 'Partner API read endpoints for leads, users and branches (product request 2026-09-29), on the existing iam.api_clients key system -- no new table, token type or issuance endpoint. New auth-constants scopes leads:list (GET /public/v1/leads: filter by branch_id, assigned_to, source, stage, outcome -- csv, source/stage/outcome by uuid or catalog name -- start_date/end_date, include_inactive, limit<=500/offset) and leads:find (POST /public/v1/leads/find: arrays of phones and emails, <=100 combined; phones match on the last 10 digits, emails on trimmed lowercase; each row reports matched_on and unmatched inputs come back under not_found). Separate from leads:read on purpose: keys already issued for single-lead lookups must not silently gain the tenant''s whole lead book. Both return contact + CRM state (branch, source, stage, outcome, assignee, next follow-up) but never raw_webhook_data, metadata, tags, outcome_comment or campaign internals. GET /public/v1/users gains department_id (the department of the role held in that branch), manager_id and csv branch_id filters, and now returns branch_id/branch_name/department_* per membership row; GET /public/v1/branches takes csv branch_id. SECURITY FIX in the same change: a key bound to SEVERAL branches that sent no branch_id used to get /users and /branches for the WHOLE tenant; every one of these endpoints is now fenced to the key''s X-Allowed-Org-Ids, and a requested branch outside the key''s reach is a 400. /users also requires the membership''s branch, not only the user''s home branch, to be in the key''s tenant. Tenant is never a parameter: it comes from the verified key. scopes is an unconstrained TEXT[], so there is no DDL; existing keys are unchanged until an admin ticks the new scopes on the API Tokens screen.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.54.0', 'E2E validation cycle 4 fixes (2026-09-29, open_issues/openissues-cycle4.md). (1) SECURITY: identity-service switchOrg filed a DENIED switch (org_switch_denied) under the org the caller ASKED for, which may belong to another tenant -- that tenant''s admins saw the caller''s user id in GET /activities, and any user could write rows into any tenant''s audit trail. It is now filed under the caller''s own verified org; existing rows are moved to the performer''s home org by one_time/apply_rehome_org_switch_denied.sql (+ _dryrun). (2) GET /activities returned 500 "permission denied for schema audit" for every non-tenant role: leads-service reads as lms_svc (NOINHERIT), which had no USAGE on schema audit. 07_grants.sql grants lms_svc USAGE on audit + SELECT on audit.activities (RLS already names lms_svc). listActivities gains an explicit session-tenant predicate (a super_admin transaction bypasses RLS, so it read every tenant''s feed), and the controller''s rank gate is replaced by the lms.history.view.org capability.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.55.0', 'Super admin tenant switch, strictly fenced (2026-09-29). A platform super_admin can now switch its session into a branch of ANY tenant from the navbar of every app (identity-service switch-org/my-orgs; findUser admits u.platform_role = super_admin from the DB row, never the token, for an active branch of an active tenant; tenant_name now names the TARGET tenant; switch-org {all_branches, tenant_id} is super_admin-only; a cross-tenant switch is audited in BOTH tenants (org_switch under the new branch, org_switch_out under the old) and each row carries only { cross_tenant: true } -- never the other tenants ids, since GET /activities is read by that tenants admins). SECURITY: @platform/db withRoleTx used to run super_admin on root_service (BYPASSRLS), so every RLS-only read returned every tenant''s rows whatever tenant the session was in; it now runs super_admin as tenant_admin with app.current_tenant_id pinned to the session tenant, so every screen shows only that tenant. Deliberately cross-tenant super_admin work (lookup-admin consoles) already uses withTenantConfigTx / withServiceTx and is unaffected. DDL: task.task_comments gains GRANT INSERT to tenant_admin and tenant_self_insert_policy (own author rows, any branch of the session tenant) -- tenant admins could not comment on tasks at all, and a switched super_admin would have lost it. Existing servers: one_time/apply_super_admin_tenant_fence.sql (+ _dryrun), or apply_schema.ps1 (re-runs 07/08).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.55.1', 'Audit feed tenant isolation (2026-09-29): org_switch / org_switch_out / org_switch_denied rows name only ids of the tenant whose feed they are filed under. identity-service stops writing another tenant''s branch/tenant ids into switch audit meta (a denied switch to another tenant''s branch now records requested_other_tenant: true instead of requested_org_id; cross-tenant switches record cross_tenant: true), and one_time/scrub_foreign_switch_audit.sql (+ _dryrun) rewrites rows already stored. Caught by the super-admin tenant-switch leak sweep: GET /activities showed Fitclass admins MSquare branch ids from denied switches (1.54.0 rehomed those rows but kept requested_org_id). No DDL.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.56.0', 'HRMS left nav gains Employees and Reports; combined (multi-branch) attendance muster report (product request 2026-09-30). CAPABILITIES: attendance reports leave the Reports TAB of Attendance admin for their own tool -- hr.reports (tool) / hr.reports.attendance (page) / hr.reports.attendance.view (operation) with scopes .view.org (session branch) and .view.tenant (every branch of the tenant). hr.attendance.admin.reports and .view are DEACTIVATED (fn_role_capability_matrix walks active nodes only), not deleted: their grant rows are the pin for the back-fill in reference_data/03_roles_and_grants.sql, which gives every EFFECTIVE holder (a grant row pruned by a denied ancestor is skipped, so e.g. an org_admin a tenant cut off from attendance gains nothing) -- global templates and per-tenant copies -- the tool, view and .org, and tenant_admin / hr_admin / super_admin also .tenant. WHY a tool and not a tab: reading payroll reports is a different audience from configuring rules and shifts, and the report now needs a branch-reach ladder the admin page never had. hr-service: GET /attendance/reports/summary and /detail re-gated on hr.reports.attendance.view (the extra hr.attendance.admin service check is dropped -- reports are no longer an admin-config concern). New GET /attendance/reports/muster?month&branch=current|all&org_id&format=json|xlsx (gateway /hr/attendance/reports/muster): one row per employee with designation, department, date of joining and branch, one P / A / HD / L / HD/L / LOP / WO / H cell per day, Total Present Day (half day = 0.5), Weekoff Paid (every weekly off inside employment), Paid Leave (hr.leave_types.is_paid), Holidays, Total Paid Days, and a blank Final Paid Days for HR. branch=all needs scope tenant; the branch list is always derived server-side from the gateway-verified tenant, and an org_id outside it is a 403. Read on the service transaction like the detail report (attendance RLS lets app_user read only its own rows), pinned to that server-derived list. hr-web: Reports and Employees become left-nav pages (/reports, /employees); the Reports tab leaves Attendance admin and the Employees tab leaves Leave admin. Employees is gated on the existing hr.employees tool -- no new capability. Existing databases: db_scripts/one_time/apply_hr_reports_capability.sql (+ _dryrun.sql). No DDL.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.57.0', 'Branding, personal appearance and self-service password reset (Stitch redesign, gate 0b, 2026-10-03). NEW TABLES: entity.tenant_branding (one row per tenant, PK tenant_id; absent = platform default): theme preset / seed_hex / font / default_mode + theme_locked, brand assets (logo, dark logo, mark, favicon, PWA icon — blob keys in assets jsonb), product_names, terms, nav_overrides, and a random rotatable public_key used ONLY by the tenant login link (/login?t=) to show branding before sign-in — it authorises nothing. OWNERSHIP IS SPLIT AND ENFORCED IN THE DB: tenant admins (capability admin.branding.manage, withRoleTx) get column-level INSERT/UPDATE on theme + terms + nav_overrides only (07_grants.sql); assets, product names, public_key and theme_locked are written only by Super Admin through admin-service under root_service; a BEFORE UPDATE trigger (entity.guard_tenant_branding_theme_lock) refuses theme changes from any login but root_service / a superuser while theme_locked — an allow-list, because product-scoped logins (lms_svc etc.) do not SET ROLE. RLS: every member of the tenant may read its row (tenant via current org for app_user, current tenant for tenant_admin). preset / font / default_mode are TEXT + CHECK, not lookup FKs: the lists are a code-owned registry (@platform/ui-kit/theme presets.ts; fonts must be declared to next/font at build time) and a lookup table would be a second copy; precedent lms.lead_assignment_log.action. iam.user_preferences (personal; theme jsonb, NULL = company theme): RLS user_id-only for every role, tenant_admin included. iam.password_reset_tokens: SHA-256 hash only, single use, 15-minute life; RLS on with NO application policy (deny-all) plus explicit REVOKE — identity-service uses it only under root_service because no session exists before a reset. CAPABILITIES: platform.appearance (operation under platform; every role, incl. read_only — personal, changes nothing shared), admin.branding (page under admin) + admin.branding.view / admin.branding.manage (tenant_admin; super_admin via *). Existing databases: db_scripts/one_time/apply_branding_appearance_reset.sql (+ _dryrun.sql), which back-fills platform.appearance wherever the platform tool is granted and admin.branding.* to the tenant_admin role template and every per-tenant tenant_admin copy, with DO NOTHING so a tenant opt-out survives.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.58.0', 'Bulk lead actions (Stitch redesign plan 3.2, 2026-10-04). NEW CAPABILITIES (operations, no DDL): lms.leads.bulk.update (under lms.leads) and lms.followups.bulk.reschedule (under lms.followups), gating POST /leads/bulk. Back-filled to every EFFECTIVE holder of lms.leads.assign.bulk -- global templates and per-tenant copies -- with DO NOTHING so a tenant opt-out survives (reference_data/03_roles_and_grants.sql; existing databases: one_time/apply_bulk_actions_capabilities.sql + _dryrun.sql). POST /leads/bulk takes lead_ids (<=200) and one action: set_stage, log_call or reschedule (reassigning stays on POST /assignments/bulk). Every lead runs through the SAME service path as its single-lead route (RLS, stage rules, hierarchy checks, audit, events), so nothing is looser in bulk; a lead that fails is SKIPPED with its reason and the rest still apply (no all-or-nothing). POST /assignments/bulk gains mode round_robin + assignee_ids: the selected leads (one branch) are dealt across exactly the people named, in order, each checked against the leads'' branch; an ineligible person is left out with a warning, and the response carries distribution and warnings. No cap or weights. Only the capability catalog and grants change; leads, follow-ups and interactions keep their tables.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.59.0', 'HRMS Stitch redesign H2: comp-off claims (2026-10-04). NEW TABLE hr.comp_off_claims (user_id, org_id, worked_date, days in {0.5,1.0}, reason, status pending/approved/rejected/cancelled, approver_id, acted_by/at, approver_comment, leave_type_id, ledger_entry_id, expires_on, lapsed_at + the standard columns): an employee who worked a day off claims a day back; the level-1 approver the leave chain resolves at submit time -- or an authorized override -- decides it. Approval credits hr.leave_ledger (entry_type adjustment, note Comp-off credit) on the tenant''s active leave type named comp_off and stamps expires_on (90 days); the nightly job writes a lapse entry once expired, capped at the current comp_off balance so the ledger never goes negative because of it. Consuming a comp-off day is an ordinary leave request against the comp_off type -- nothing about requests, approvals or balances changes. The comp_off leave type (Compensatory Off) is already seeded for every tenant by the leave_types catalog (reference_data/07_catalog_registry.sql); a tenant that has deactivated it gets a claim refused with that explanation. One live claim per (user, worked_date) (partial unique index; a rejected or cancelled claim frees the date). RLS: org_isolation + tenant_isolation + self_policy (the attendance_regularizations shape); decisions and the expiry sweep run in the service transaction. NEW CAPABILITIES (operations under hr.leave): hr.leave.comp_off.request (Claim comp-off) and hr.leave.comp_off.approve (Decide comp-off), back-filled from EFFECTIVE holders of hr.leave.request.create and hr.leave.approve respectively, DO NOTHING so a tenant opt-out survives. No capability was added for the bulk leave decision endpoint (POST /hr/leave/requests/bulk-decision): it checks hr.leave.approve / hr.leave.reject for the chosen decision and runs every request through the single-request path. Existing databases: db_scripts/one_time/apply_comp_off.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.60.0', 'HRMS Stitch redesign H3: Employee 360 data (2026-10-04). NEW TABLES hr.employee_personal (one row per user: preferred_name, date_of_birth, gender, marital_status, blood_group, nationality, personal_email, current/permanent address), hr.emergency_contacts (name, relation, phone, is_primary; at most one primary per person) and hr.employee_notes (HR timeline: note/appraisal/promotion/transfer/warning/other). PRIVACY SHAPE, deliberately not the usual org-wide policy: everyone in an org may read the employee directory, but a colleague''s date of birth, address and emergency contacts are not theirs to read, so employee_personal and emergency_contacts carry a SELF policy for app_user (own rows) and a tenant_admin policy and NO org_isolation policy, and employee_notes carries no app_user policy at all (an HR note is not the employee''s to read). Anyone else -- an HR admin opening an Employee 360 -- reads and writes through the service transaction after hr-service has checked hr.employees.profile360.view / hr.employees.notes.manage. Closed value sets are CHECK-constrained TEXT, the house style for small fixed lists (accrual_frequency, leave_ledger.entry_type). NEW CAPABILITIES under hr.employees: hr.employees.profile.edit (own personal details + emergency contacts), hr.employees.profile360.view (open any employee''s full profile) and hr.employees.notes.manage (HR notes), back-filled from EFFECTIVE holders of hr.employees.view / hr.employees.manage / hr.employees.manage, DO NOTHING so a tenant opt-out survives. NOT in this version, deliberately: statutory identifiers and bank details (PAN, Aadhaar, UAN, account number). They need an encryption-key decision (where the key lives, who may reveal a value, rotation) that has not been made, so no column for them exists yet. Existing databases: db_scripts/one_time/apply_employee_360.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.61.0', 'HRMS Stitch redesign H4: team roster + peer shift swap (2026-10-04). NEW TABLE hr.shift_swap_requests (org_id, requester_id, peer_id, swap_date, requester_shift_id, peer_shift_id, reason, status pending_peer/pending_manager/approved/rejected/declined/cancelled, manager_id, peer_responded_at, acted_by/at, approver_comment + the standard columns). Two employees trade shifts for ONE FUTURE day: the requester asks, the peer consents, then the requester''s level-1 approver (resolved through the leave chain, as for comp-off) or an authorized override decides. APPROVAL REWRITES hr.shift_assignments in one transaction for BOTH people: the assignment covering the day is shrunk to end the day before (or soft-deleted when it starts that day), a one-day row carrying the OTHER person''s shift is inserted, and a continuation row carrying the original shift resumes the day after -- the excl_shift_assignments_no_overlap gist constraint is satisfied because the rows only ever touch end to end. Only future days can be swapped, so no attendance day has been resolved and nothing needs recomputing. Rules enforced server-side (lib/attendance/swap.ts, pure and unit-tested): the day must be in the future, both people must have a shift that day and neither may be on a weekly off, holiday or approved leave, the two shifts must differ, and an 11-hour rest gap must hold on both sides of the day for BOTH people after the swap (previous day''s end to the new start, and the new end to the next day''s start). One OPEN swap per person per day (partial unique indexes, plus a service check that stops someone being requester in one swap and peer in another on the same day). PRIVACY: only the participants (requester, peer, manager) may see a request -- a swap reason is between colleagues and their approver -- so the table has a participant SELECT policy for app_user and a tenant_admin policy and NO org-wide policy; every write runs in the service transaction. NEW CAPABILITIES (operations under hr.attendance): hr.attendance.roster.view, hr.attendance.swap.request, hr.attendance.swap.approve, back-filled from EFFECTIVE holders of hr.attendance.view, hr.attendance.punch and hr.attendance.regularization.approve respectively, DO NOTHING so a tenant opt-out survives. The roster reads people the caller manages or shares a manager with, in the service transaction, behind roster.view. Existing databases: db_scripts/one_time/apply_shift_swap.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.62.0', 'HRMS Stitch redesign H5: payslip viewer + payroll month lock (2026-10-04). NOT a payroll engine -- no PF/ESI/PT/TDS computation, no salary structures, no bank file; HR prepares each employee''s payslip lines and publishes them. NEW TABLES hr.pay_periods (one row per org and month, status open/locked; an absent row means open), hr.payslips (one per employee and month: working_days, lop_days, gross, deductions, net, published_at) and hr.payslip_lines (earning/deduction rows, amount >= 0). Gross, deductions and net are COMPUTED from the lines by the service, never trusted from the client. PRIVACY: salary is the most sensitive data in HR, so there is NO org-wide policy -- an employee reads only their own payslip and only once it is published (self policy with published_at IS NOT NULL; payslip_lines readable exactly when their payslip is), tenant_admin has a tenant policy, and HR drafts, publishes and reads others'' payslips through the service transaction behind hr.reports.payroll.manage. pay_periods is readable by anyone in the branch (a lock is not secret; the attendance correction paths read it inside the caller''s own transaction) and writable only through the service. THE MONTH LOCK: when a month is locked, creating or approving an attendance regularization for a date in it, and recomputing attendance across it, are refused with a clear message; unlock is a separate act. Live punches and the nightly resolve job are deliberately NOT blocked (they work on the current day), and a deployed check at the two human-driven correction paths plus recompute is what protects the figures HR took to payroll. NEW CAPABILITIES: hr.employees.payslip.view (own payslips, back-filled from effective holders of hr.employees.view) and hr.reports.payroll.manage (prepare, publish, lock; back-filled from hr.employees.manage), DO NOTHING so a tenant opt-out survives. Existing databases: db_scripts/one_time/apply_payroll_viewer.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.63.0', 'HRMS Stitch redesign H6: announcements and assets (2026-10-04). NEW TABLES hr.announcements (title, body, category general/policy/event/celebration, is_pinned, published_at, expires_on), hr.announcement_reads (announcement_id + user_id, read_at), hr.assets (asset_tag unique per org, name, category laptop/monitor/phone/access_card/other, serial_no, status in_stock/assigned/retired) and hr.asset_assignments (asset, employee, assigned_on, returned_on; an asset is held by at most one person at a time -- partial unique index on open assignments). RLS: announcements are readable by everyone in the branch once PUBLISHED and unexpired (drafts are HR''s), announcement_reads carries a self policy so a person records and reads only their own reads, and assets plus assignments have NO app_user policy at all -- inventory is HR data, and an employee sees what they hold through the service transaction, own rows only, behind hr.employees.assets.view. Announcement writes and asset writes are service-transaction only behind the manage capabilities. NEW CAPABILITIES under hr.employees: announcements.view / announcements.manage / assets.view / assets.manage, back-filled from EFFECTIVE holders of hr.employees.view (the two view ones) and hr.employees.manage (the two manage ones), DO NOTHING so a tenant opt-out survives. Existing databases: db_scripts/one_time/apply_announcements_assets.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.64.0', 'HRMS Stitch redesign H7: leave SLA / request-more-info / encashment, statutory and bank details, profile change requests, manual punches (2026-10-04). LEAVE: hr.leave_policies gains sla_hours (default 48; the approval window shown as a countdown, never an auto-decision), encashable (default false) and max_encash_days; hr.leave_requests gains info_requested_at and info_request_note -- "request more info" does NOT add a status: the request stays pending, the approver''s question is stored on it, and the requester answering by editing the request clears it (the existing PATCH). hr.vw_leave_requests_enriched appends info_requested_at, info_request_note and the effective sla_hours. NEW TABLE hr.leave_encashment_requests (days > 0, status pending/approved/rejected/cancelled, approver, ledger_entry_id; one open request per person and type): approval writes a NEGATIVE encashment entry on hr.leave_ledger, refused unless the type''s policy is encashable, the days fit max_encash_days and the balance covers them. NEW TABLE hr.employee_statutory (PAN, Aadhaar, UAN, bank name/branch/account/IFSC/account type, tax regime; format CHECKs) -- STORED AS PLAIN TEXT for now by product decision (encryption comes later: where the key lives, who may reveal and rotation are open). Until then the protection is access control only: a self policy and a tenant_admin policy and NO org-wide policy, the API masks every value except for the owner and for hr.employees.statutory.manage, and each read or write by someone else writes an audit row. When encryption lands the columns become ciphertext + last-4 and the masking already in the API stays. NEW TABLE hr.profile_change_requests (section statutory, payload jsonb, status, reviewer): an employee asks HR to change their statutory/bank details, HR approves (the payload is applied in the same transaction) or rejects; one open request per person. hr.attendance_events.source gains manual: a punch added by HR on someone''s behalf (the reason and the acting user are kept in device_info) -- never produced by a client. NEW CAPABILITIES: hr.attendance.admin.override (manual punch, bulk regularize, nudge; back-filled from hr.attendance.admin.assignments.manage), hr.leave.encashment.request / .approve (from hr.leave.request.create / hr.leave.approve), hr.employees.statutory.manage (from hr.employees.manage); effective holders only, DO NOTHING so a tenant opt-out survives. Existing databases: db_scripts/one_time/apply_hr_h7.sql + _dryrun.sql (adds the columns, the constraint change, the tables, the view and the capabilities; apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.65.0', 'HRMS Stitch redesign: documents & compliance vault (2026-10-04). NEW TABLE hr.employee_documents: an employee''s uploaded paperwork -- category (id_proof/address_proof/education/employment/tax_proof/medical/other), title, file_key + file_name + mime_type (pdf/jpeg/png/webp) + size_bytes (<= 3 MiB, enforced by CHECK), review state pending/verified/rejected with reviewer, time and note (CHECK: reviewed_at is set exactly when the status is not pending), optional expires_on, and for tax proofs an optional tax_section and amount. The bytes live in blob storage under documents/<org>/<user>/..., never in the row. PRIVACY: identity paperwork, so there is NO org-wide policy -- an employee reads only their own rows (self policy, app_user SELECT only), a tenant_admin has a tenant policy, and every write plus HR''s reads of other people''s files run in the service transaction behind hr.employees.documents.manage, org-fenced, with an audit row per access to someone else''s file. Delete is a soft delete done by an UPDATE in the service (the DELETE trigger is only honoured for root_service). NEW CAPABILITIES under hr.employees: documents.view (own documents; back-filled from EFFECTIVE holders of hr.employees.view) and documents.manage (verify / read anyone''s; from hr.employees.manage), DO NOTHING so a tenant opt-out survives. Existing databases: db_scripts/one_time/apply_documents_vault.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.66.0', 'HRMS Stitch parity: employee profile fields, configurable document limit, roster planner (2026-10-04). EMPLOYEE PROFILES gain grade, squad, cost_center, notice_period_days (0-365), work_mode (office/hybrid/remote) and seat_label, all optional; they fill the directory, Employee 360 and dashboard cards. DOCUMENTS: hr.employee_documents.size_bytes CHECK raised from 3 MiB to 3.5 MiB (3670016), the ceiling at which a base64 body still fits the 5 MB request limit; NEW TABLE hr.document_settings (one row per org, max_bytes 100 KiB..3.5 MiB, default 3 MiB) lets HR set the limit within that ceiling. ROSTER PLANNER: NEW TABLES hr.shift_requirements (people a shift needs per branch; drives the capacity cards) and hr.roster_publications (a Monday-dated week that HR has published, by whom and when). All three are readable by the branch (app_user SELECT, tenant_admin policy) and written only through the service transaction. NEW CAPABILITY hr.attendance.roster.manage (open the planner, assign/change/clear shifts for a day or range, set requirements, publish), back-filled from EFFECTIVE holders of hr.attendance.admin.assignments.manage, DO NOTHING so a tenant opt-out survives. Planner edits reuse hr.shift_assignments: a one-day change carves the day out of the person''s assignment (the same split the shift swap uses), so the table''s no-overlap exclusion still holds. Existing databases: db_scripts/one_time/apply_planner_profile_fields.sql + _dryrun.sql, which also runs the service-login policy sweep (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.67.0', 'HRMS Stitch parity: leave apply page (2026-10-05). hr.leave_requests gains request_no (BIGINT from hr.leave_request_no_seq, starting at 1001, shown as LV-1001; existing rows are numbered in created_at order), handover_user_id (the colleague covering the work; ON DELETE SET NULL) and the uploaded supporting document as attachment_key / attachment_name / attachment_mime / attachment_size (the bytes live in blob storage under leave/<org>/<user>/..., never in the row; document_url stays for a pasted link). hr.vw_leave_requests_enriched appends request_no, handover_user_id, handover_name, attachment_name, attachment_mime, attachment_size and latest_approver_name (the reviewer), so every consumer of the view picks them up. No new table, so no new RLS; the sequence needs USAGE for the logins that insert requests (granted in 07). Saved drafts are deliberately NOT a server state: a draft is kept in the browser, because a draft status would have to be honoured by balance, overlap, approver-queue and attendance logic that all treat every non-terminal status as an open request. Existing databases: db_scripts/one_time/apply_leave_apply_page.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.68.0', 'ToDo Stitch redesign: task codes, SLA state, bulk + export capabilities (2026-10-04). task.tasks.task_no BIGINT NOT NULL -- a per-branch (org) running number shown as TASK-<n>, unique per org (uq_tasks_org_task_no), assigned by the new SECURITY DEFINER BEFORE INSERT trigger trg_02_tasks_assign_no / task.assign_task_no() from the new table task.task_counters (RLS on, no policy, no grant to app_user / tenant_admin / task_svc: unreachable from a request; the upsert row-locks the org counter so concurrent inserts cannot draw the same number; a caller-supplied value is always overwritten). Existing rows are numbered oldest-first per org with the audit and updated_at triggers disabled for the back-fill. task.vw_tasks_enriched gains, appended at the end, task_no, org_name and sla_state (none | ok | due_soon (< 24h) | overdue, derived from due_at; finished tasks are always none -- there is no SLA policy table). NO list-scope change: a branch IS an organization, so the existing org visibility is the design''s Branch scoped tier (UI relabel only). NEW CAPABILITIES under tasks: bulk (reassign / change status on many tasks; back-filled from EFFECTIVE holders of tasks.assign) and export (CSV of the visible tasks; from tasks.view.team), DO NOTHING so a tenant opt-out survives. Existing databases: db_scripts/one_time/apply_task_codes_bulk_export.sql + _dryrun.sql, THEN apply_schema.ps1 for the view/index/grants/RLS (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.69.0', 'Super Admin Stitch redesign: Meta ad account fetch errors (2026-10-05). ext.meta_ad_accounts gains last_error (TEXT, NULL = clean) and last_error_at: the campaign fetch records why an account failed and clears both on its next clean walk, so the Ad Accounts page can filter to accounts with errors. Platform-level table, RLS unchanged (no app_user policy; service transaction from super_admin routes only). Existing databases: db_scripts/one_time/apply_ad_account_errors.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.70.0', 'Super Admin Stitch redesign: Meta console tables (2026-10-05). ext.meta_campaigns gains is_archived / archived_at / archived_by (hide from the Campaign Mapping working lists; visibility only, an archived campaign keeps routing). scratch.meta_pull_leads gains apply_selected (default TRUE) so Apply can import a chosen subset; unticked rows are marked skipped by the apply worker. scratch.meta_pull_runs.status gains discarded, plus discarded_by / discarded_at. NEW TABLE ext.meta_page_health (tenant_id + page_id unique: token_status ok/missing/expired/error, is_subscribed, error_text, checked_at) holding the last Validate-page-tokens result, and NEW TABLE ext.meta_pull_run_history (one summary row per pull run: filters, tallies, status, who and when -- no lead details) because the scratch tables keep only the latest run. Both are tenant-pinned with the N-6 admin policy and granted to lms_svc / meta_svc / app_user / root_service (not tenant_admin). Indexes: partial on archived campaigns, inbox (tenant_id, status, reason) for the unmapped-inbound count, history by tenant. Existing databases: db_scripts/one_time/apply_meta_console_1_70.sql + _dryrun.sql (apply_schema.ps1 never re-runs 02/03).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.71.0', 'Fix: GET/PUT /lookups/lead-stage-capi-events failed with permission denied for table lead_stage_capi_event_map (2026-10-06). leads-service connects as the NOINHERIT login lms_svc, which does not inherit app_user''s grants; the table, ext.meta_capi_event_types and the two views were granted to app_user only. lms_svc now holds SELECT/INSERT/UPDATE/DELETE on ext.lead_stage_capi_event_map and SELECT on the event-type table and both views; app_user gains DELETE (clearing a stage''s event is a real delete). Policies already reached lms_svc. Existing databases: db_scripts/one_time/apply_capi_event_map_grants.sql + _dryrun.sql.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.72.0', 'Multi-level approvals: one person can no longer approve two levels of the same leave/regularization request (2026-10-06). hr.leave_request_approvals and hr.attendance_regularization_approvals gain acted_by (who actually decided; approver_id stays the designated approver, so an hr_admin override is now recorded as itself). The service refuses a decision from anyone who already approved an earlier level (COALESCE(acted_by, approver_id)). New views hr.vw_leave_approval_summary / hr.vw_regularization_approval_summary give the list screens levels approved of total, who it is pending with and who approved. Cover-and-escalate rule: a higher approver may approve a lower pending level on its approver''s behalf (counts as their one approval); their own level is then reassigned (hr.*_approvals.reassigned_from) to the next manager up, else another hr_admin/org_admin, else a tenant_admin. Back-fill: acted_by from the approver on decided rows, from the "[override by <uuid>]" comment where an override acted.'),
  ('1.73.0', 'Tenant branding grows up (2026-10-06): entity.tenant_branding gains locale_config (regional formats: locale, date/time format, timezone default, week start, currency, number grouping, fiscal year start, phone code; whitelisted keys validated in the API) and branding_version (bumped by trigger on every UPDATE, cache key for the public JSON/manifest). Brand image slots grow from 5 to 13 (app_icon_maskable, apple_touch_icon, icon_192, push_icon, push_badge, email_logo, login_hero, splash). OWNERSHIP: the tenant admin (admin.branding.manage) may change colour, font and default light/dark mode only (column GRANTs on preset, seed_hex, font, default_mode, updated_by); images, product names, renamed terms, menu labels/icons and regional formats are Super Admin''s (service tx). terms and nav_overrides were tenant-writable before; the one-shot REVOKEs them. Blob keys move to the tenant-first layout <tenant_id>/branding/<slot>/<ts>.<ext> and <tenant_id>/<branch_id>/<employee_id>/avatar|punches|documents|leave; legacy keys keep resolving until migrate-blob-layout runs. One-shot: one_time/apply_branding_locale.sql (+ _dryrun).'),
  ('1.74.0', 'Race backstops (2026-10-06, from the cycle-6 E2E run). Two partial UNIQUE indexes, no column changes: uix_leave_ledger_consumption ON hr.leave_ledger(leave_request_id) WHERE entry_type=''consumption'' (approve + approve inserted two consumption rows, debiting the employee''s balance twice) and uix_lead_links_transfer_source ON lms.lead_links(source_lead_id) WHERE link_type=''transfer'' (two simultaneous transfers copied the lead twice). The services now row-lock first (hr-service loadRequestForAction FOR UPDATE; leads-service transferLead source SELECT FOR UPDATE); the indexes make a lost race a 23505 -> 409. Existing databases: db_scripts/one_time/apply_race_backstop_indexes.sql (refuses to run while duplicates exist) + _dryrun.sql, which lists them.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.75.0', 'Fine-tuned theme colours (2026-10-06). entity.tenant_branding gains color_overrides JSONB NOT NULL DEFAULT ''{}'' -- a SPARSE { light: { <role>: #rrggbb }, dark: { ... } } map of colour roles changed by hand (about 23 brand / secondary / tertiary / surface / text / outline roles; error and status roles are fixed and rejected); every role not listed keeps following the seed, so changing the seed later still works. CHECK chk_tenant_branding_color_overrides = JSON object whose only keys are light and dark; role names, hex format and the 3:1 contrast floor (on-colour vs its background) are enforced by the API. It is part of the THEME: the tenant admin may write it (column GRANT in 07 alongside preset / seed_hex / font / default_mode) and the existing theme-lock trigger now freezes it too, so Super Admin''s lock covers it at the database. Super Admin writes it through the service transaction. A user''s own override needs no new column: iam.user_preferences.theme (JSONB) carries theme.color_overrides in the same shape, allowed only while the tenant theme is unlocked. Layering: platform default -> tenant (seed + overrides) -> user; a user who picks a different seed drops the tenant overrides for themselves. Existing databases: db_scripts/one_time/apply_color_overrides.sql + _dryrun.sql, THEN apply_schema.ps1 (trigger + grants), BEFORE the new identity-service image (its SELECT names the column).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.76.0', 'Capability walls (2026-10-08). Every screen, tab and call that decided by rank or role name moves behind a capability; the cutover is behaviour-neutral (explicit tenant and template grants reproduce today''s access). NEW operations, back-filled to current holders: lms.leads.export, hr.employees.statutory.view, hr.leave.admin.tenant_wide, hr.attendance.admin.tenant_wide, admin.api_tokens.tenant_wide. MERGED: hr.leave.reject into hr.leave.approve and hr.attendance.regularization.reject into hr.attendance.regularization.approve (a role that held only approve gains reject). REMOVED, no reader: lms.dashboard(.view), lms.leads.edit.{own,team,any}, lms.history.detail.view (use lms.history.view), lms.history.view.team, tasks.view.own, tasks.edit.{own,team}, hr.attendance.view.{own,org}, hr.leave.view.{own,team}, hr.leave.admin.holidays.view, hr.attendance.admin.reports(.view). WIRED: lms.leads.unassigned.view, lms.analytics.org.view and the lms.history.view.* ladder now decide what rank and role name used to; org_manager/org_sr_manager lose lms.leads.delete (they never could use it: the route also required rank 980). Existing databases: db_scripts/one_time/apply_capability_walls.sql (dry-run recipe in its header). No DDL.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.77.0', 'Configurable minimum rest between shifts (2026-10-08). hr.attendance_rules.min_rest_hours (SMALLINT NOT NULL DEFAULT 11, CHECK 0..24; tenant default row with an org override, like every other attendance rule) replaces the hard-coded 11-hour rule; hr.shifts.min_rest_hours (nullable, CHECK 0..24) lets one shift override it, and the gap between two shifts is judged by the setting of the shift that STARTS after it. 0 turns the rule off. The roster planner no longer silently skips a person who would break it: nothing is written, the break comes back as a warning, and the planner re-sends with confirm_rest_warnings to apply it anyway (recorded in the audit log as rest_warning_confirmed). Shift swaps still refuse but now honour the same policy. Existing databases: db_scripts/one_time/apply_min_rest_hours.sql (+ _dryrun.sql); existing rows get 11, so behaviour is unchanged until someone edits the policy. Deploy the SQL BEFORE the new hr-service image (its SELECTs name the columns).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.78.0', 'Fix: tenant_admin and super_admin could not create or edit departments (2026-10-09, from the cycle-7 E2E run). iam.departments granted tenant_admin SELECT only and its policy was FOR SELECT, so POST /hr/employees/departments failed with permission denied -> 500. tenant_admin now holds INSERT/UPDATE and its tenant_isolation_policy is FOR ALL with a WITH CHECK pinned to the tenant. Who may write stays an app-layer (capability) decision. The one-shot also enables RLS (deny-all) on the leftover iam.*_bak_* capability backup tables (data-health RLS-2). No column changes. Existing databases: db_scripts/one_time/apply_departments_tenant_admin_write.sql + _dryrun.sql.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.79.0', 'Meta Conversions API v2 (2026-10-09). Conversion events now go to the dataset (pixel) of the ad account that generated the lead, through two platform system-user credentials and a transactional outbox, instead of one pixel + one token per tenant. NEW, root_service only (RLS on, no policy -- the ext.meta_ad_accounts treatment): ext.meta_platform_credentials (purpose LEADS_READ | CAPI_WRITE, encrypted token, scopes, expiry, one ACTIVE row per purpose), ext.meta_business_portfolios (a partner portfolio, owned by exactly one tenant), ext.meta_datasets (a pixel; composite FK (tenant_id, portfolio_id) so it cannot be filed under another tenant), ext.meta_dataset_ad_accounts (the routing key; UNIQUE ad_account_id = the 1:1 the business runs on), ext.meta_org_dataset_map (per-branch FALLBACK; composite FKs to the tenant''s organizations and datasets). NEW, tenant+org scoped: ext.meta_capi_outbox -- one row per event, written IN the stage-change transaction; event_time is the stage-change time; UNIQUE (dataset_id, event_id) makes enqueueing idempotent; expires_at = event_time + 7 days; status PENDING/SENDING/SENT/FAILED/DEAD/EXPIRED plus SKIPPED_* so every lead that never reached Meta has a reason; RLS: an org user can read and enqueue their own org''s rows but not update them, the console path (withTenantConfigTx) is tenant-pinned, tenant_admin reads the tenant. ALTERED: ext.meta_leads gains ad_account_id, capi_dataset_id, capi_resolution (the dataset is decided ONCE at ingestion -- a lead later transferred between branches still reports to the pixel whose ad generated it); ext.meta_capi_event_types gains funnel_rank + is_negative and the catalog is now Lead / ContactedLead / QualifiedLead / ConvertedLead / UnqualifiedLead (negative), with Other retired (inactive) -- Meta wants stages in order, so the outbox enqueues the stages a lead jumped over; the template stage map becomes new->Lead, contacting->ContactedLead, qualified->QualifiedLead, converted->ConvertedLead, unqualified->UnqualifiedLead, on_hold / transferred_out unmapped (the one-shot re-wires a tenant only where a stage is still on Other, so customised stages are kept); ext.meta_page_health gains leads_access_ok; entity.organizations gains UNIQUE (tenant_id, id) for the composite FKs; ext.meta_tenant_config.pixel_id / access_token lose NOT NULL (deprecated: read only as a fallback until the credentials are entered) and capi_trigger_stages / ad_account_ids leave the CREATE (existing databases keep them until apply_meta_capi_v2_drop_dead_columns_1_80.sql, run after the new images ship). Views vw_meta_capi_event_types and vw_lead_stage_capi_event_map gain funnel_rank / is_negative (and stage_sort_order). Rolled out with db_scripts/one_time/apply_meta_capi_v2_1_79.sql (+ _dryrun) BEFORE the new meta-conversion-api, leads-service and lookup-admin images.')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.81.0', 'Attendance face match moves in-process (2026-10-10). The CompreFace integration (never switched on in any environment: COMPREFACE_API_KEY was blank everywhere, so every face-required punch fell through to pending review) is removed entirely and replaced by an ONNX engine inside hr-service: YuNet detection, SFace 128-d embeddings and a MiniFASNet anti-spoof (liveness) check, all Apache-2.0, models committed under msq-hrms/services/hr-service/models with pinned SHA-256. NEW TABLE hr.face_templates (one row per org+user: model_version, embedding_enc, quality jsonb, UNIQUE(org_id,user_id)). BIOMETRIC, so it breaks three house rules on purpose: embedding_enc is AES-256-GCM ciphertext under FACE_TEMPLATE_KEY held only by hr-service (CHECK enforces the enc:v1 envelope; the DB never sees plaintext); unenrolment HARD-deletes the row (no is_deleted / soft_delete_row); and there is no audit_row_changes trigger (it would copy ciphertext into audit.* and outlive the erasure; enrol/unenrol are audited by hr-service without template data). Access is root_service only: REVOKE ALL from PUBLIC/app_user/tenant_admin/hr_svc/analytics_svc (undoing the hr schema default privileges) and RLS FORCED with NO policy, so any non-BYPASSRLS role reads zero rows. hr.employee_profiles.face_subject_id is KEPT and now holds the hr.face_templates.id of the active template, so enrolled = face_subject_id IS NOT NULL and the API is unchanged. No business-logic change: threshold 50-100 (default 85), flag/block, fail-open on engine errors, consent, cooldown and review queue all behave as before. A probe judged a photo/screen by the anti-spoof check scores 0 (a mismatch under the existing rules), with similarity and liveness kept in attendance_events.device_info.face. Enrolment gains a quality gate (one clear face, size, pose, light, sharpness): 400 FACE_LOW_QUALITY {reason} alongside the existing FACE_NO_FACE. Existing databases: db_scripts/one_time/apply_face_templates.sql + _dryrun.sql (creates the table, trigger, index, grants and RLS, and clears the enrolment columns left by the never-run CompreFace path so those users re-enrol on their next check-in).')
INSERT INTO public.schema_versions (version, description) VALUES
  ('1.80.0', 'Meta CAPI v2 follow-up (2026-10-09): drops the dead ext.meta_tenant_config.capi_trigger_stages and ad_account_ids columns, after the v2 images shipped. POST-DEPLOY step, not part of the DB_ROLLOUT file: db_scripts/one_time/apply_meta_capi_v2_drop_dead_columns_1_80.sql (generated into msq-deploy/DB_POST_DEPLOY_*.sql). Run only when no old meta-conversion-api or lookup-admin image is left.')
